const e={brand_tagline:"مكتبة أيقونات ومجموعة أدوات تحويل دقيقة، مبنية للمطوّرين والمصمّمين.",nav_icons:"معرض الأيقونات",nav_image_convert:"تحويل الصور",nav_audio_convert:"تحويل الصوت",nav_file_convert:"تحويل الملفات",nav_drawer:"المحرر",nav_simulator:"محاكي اللمس",nav_documentation:"التوثيق",nav_apps:"التطبيقات",nav_about:"من نحن",nav_contact:"تواصل معنا",nav_faq:"الأسئلة الشائعة",read_more:"اقرأ المزيد",related_tools:"أدوات ذات صلة",other_conversions:"تحويلات أخرى",faq_heading:"الأسئلة الشائعة",home_title:"FrugalDomain — مكتبة أيقونات وأدوات تحويل الملفات",home_description:"أدوات مجانية تعمل في المتصفح من FrugalDomain: تصفّح آلاف أيقونات SVG وعدّل ألوانها وأحجامها، وحوّل الصور والصوت والمستندات، وارسم الأشكال المتجهة. بدون تسجيل وبدون حدود تنزيل.",home_heading:"أيقونات ومحوّلات وأدوات تشغيل المتاجر",home_lede:"أدوات مجانية تعمل في متصفحك مباشرة — بلا تسجيل وبلا تثبيت.",icons_title:"مكتبة أيقونات SVG مجانية — عدّلها ونزّلها | FrugalDomain",icons_description:"تصفّح آلاف أيقونات SVG وPNG المجانية. غيّر اللون والحجم وسماكة الخط داخل المتصفح، وشاهد النتيجة مباشرة، ثم نزّلها جاهزة للاستخدام — بدون حساب.",icon_library:"مكتبة الأيقونات",icons_heading_a:"مكتبة أيقونات",icons_heading_b:"SVG مجانية",icons_lede:"ابحث في آلاف الأيقونات المفتوحة، وغيّر ألوانها وأحجامها داخل المتصفح، ثم نزّلها بصيغة SVG أو PNG جاهزة للاستخدام. بدون حساب، وبدون نسب الفضل، وبدون حدود تنزيل.",icons_svg_or_png_title:"SVG أم PNG — أيّهما تختار؟",icons_svg_or_png_body:"اختر SVG عندما يجب أن تبقى الأيقونة حادّة بأي حجم: فهي مرسومة بمسارات متجهة، لذا تتمدّد من زر صغير بحجم 16 بكسل إلى رسم يملأ الصفحة دون أن تفقد حدّة حوافها. ولأن ملف SVG نص في جوهره، يمكنك تغيير لونه عبر CSS وتحريكه وتضمينه داخل الصفحة دون طلب إضافي. واختر PNG حين لا تدعم الوجهة صيغة SVG — بعض برامج البريد، وطرق العرض القديمة في أندرويد، وبعض متاجر التطبيقات — وصدّرها بالحجم الذي تحتاجه بالضبط، مع نسخة بضعف الأبعاد للشاشات عالية الدقة.",icons_licence_title:"الترخيص ونسب الفضل",icons_licence_body:"أيقونات هذه المكتبة مجانية للاستخدام الشخصي والتجاري، دون الحاجة إلى نسب الفضل ودون حدّ على عدد التنزيلات. يمكنك تغيير ألوانها وأحجامها وتعديلها، وشحنها ضمن منتج تبيعه. الاستخدام الوحيد غير المشمول هو إعادة توزيع المكتبة نفسها — أي إعادة تجميع المحتوى ونشره كحزمة أيقونات باسمك.",icons_customise_title:"التعديل قبل التنزيل",icons_customise_body:"افتح أي أيقونة لتغيير لونها عبر منتقي ألوان HEX، وضبط حجمها بالبكسل بدقة، وتعديل سماكة الخط في الأيقونات الخطّية حتى تنسجم مع وزن النص المحيط بها. تتحدّث المعاينة مع كل تعديل، والملف الذي تنزّله هو نفسه الذي رأيته — لا خطوة تصدير منفصلة قد تخطئ فيها.",icons_account_title:"هل تحتاج إلى حساب؟",icons_account_body:"لا حاجة إلى حساب للبحث أو التعديل أو التنزيل. إنشاء حساب مجاني يضيف فقط حفظ المفضلة وسجل التنزيلات ومجموعات الأيقونات المخصّصة — أمّا الأيقونات نفسها فليست محجوبة خلف تسجيل.",icons_related_title:"أدوات ذات صلة",icons_related_body:"لديك ملف ليس أيقونة؟ هذه الأدوات تحوّله داخل المتصفح:",icons_related_image:"محوّل الصور — JPG وPNG وWebP",icons_related_board:"لوح الرسم المتجه — ارسم أشكالك بنفسك",icons_related_file:"محوّل الملفات — DOCX وXLSX إلى PDF",image_title:"محوّل صور مجاني — JPG وPNG وWebP | FrugalDomain",image_description:"حوّل الصور بين صيغ JPG وPNG وWebP وغيرها مباشرة في متصفحك. سريع ومجاني وبلا حدود على حجم الملف وبلا تسجيل.",image_tools:"أدوات الصور",image_heading_a:"محوّل",image_heading_b:"الصور",image_lede:"حوّل ملفات JPG وPNG وWEBP وGIF بنقرتين. بلا حساب، وبلا علامة مائية، وبلا انتظار في الطابور.",image_why_title:"لماذا تحوّل صيغة صورة؟",image_why_body:"لكل صيغة نقطة قوّة واحدة وثمن تدفعه مقابلها. JPG تصغّر الصور الفوتوغرافية بشدّة لكنها تفقد التفاصيل ولا تدعم الشفافية. PNG تحفظ كل بكسل وتدعم الشفافية لكن ملفاتها أكبر. WebP تجمع بين الاثنتين تقريباً: حجم أصغر مع شفافية كاملة، لكنها ليست مدعومة خارج المتصفح بنفس الاتساع. اختيار الصيغة المناسبة للاستخدام المناسب هو كل ما يعنيه التحويل عملياً.",image_privacy_title:"ماذا يحدث لملفاتك؟",image_privacy_body:"التحويل خطوة واحدة: ترفع الملف، وتختار الصيغة، وتنزّل النتيجة. لا حاجة إلى إنشاء حساب، ولا علامة مائية تُضاف إلى الصورة، ولا حدّ على عدد الملفات التي تحوّلها.",image_which_title:"أي تحويل تحتاج؟",image_which_body:"إن كنت تريد تصغير صور فوتوغرافية للويب فحوّل من PNG إلى JPG أو من JPG إلى WebP. وإن كنت تحتاج شفافية فابقَ ضمن PNG أو WebP. وإن كان برنامج ما يرفض ملفاً حفظته من الإنترنت فغالباً تحتاج تحويل WebP إلى PNG.",common_conversions:"التحويلات الشائعة",common_conversions_lede:"لكل تحويل صفحته الخاصة التي تشرح أثره على الجودة وحجم الملف والشفافية.",convert_x_to_y:"حوّل {from} إلى {to}",about_converting:"عن تحويل {from} إلى {to}",all_image_conversions:"كل تحويلات الصور",free_icon_library:"مكتبة أيقونات SVG مجانية",docx_xlsx_to_pdf:"تحويل DOCX وXLSX إلى PDF",audio_title:"محوّل صوت مجاني — MP3 وWAV وOGG وAAC | FrugalDomain",audio_description:"حوّل الملفات الصوتية إلى MP3 أو WAV أو OGG أو AAC مجاناً عبر الإنترنت. ارفع الملف واختر الصيغة ونزّل النتيجة — بدون تثبيت وبدون حساب.",audio_tools:"أدوات الصوت",audio_heading_a:"محوّل",audio_heading_b:"الصوت",audio_lede:"حوّل بين MP3 وWAV وOGG وAAC مباشرة في متصفحك. بلا حساب، وبلا علامة مائية، وبلا انتظار.",audio_which_title:"أي صيغة صوتية تختار؟",audio_which_body:"MP3 هي الخيار الآمن الافتراضي: كل هاتف ومتصفح ومشغّل صُنع في العشرين سنة الماضية يشغّلها، وتضغط الكلام والموسيقى إلى جزء صغير من الحجم الأصلي. اخترها حين يجب أن يعمل الملف في كل مكان ببساطة.",audio_wav_title:"متى تحتاج WAV؟",audio_wav_body:"صيغة WAV غير مضغوطة، فلا يُحذف منها شيء. هذا يجعلها الصيغة الصحيحة للصوت الذي ما زلت تحرّره، وللمواد المصدرية التي ستعيد ترميزها لاحقاً، وللأدوات التي تتطلّب إدخالاً خاماً. والثمن هو الحجم: نحو عشرة ميغابايت لكل دقيقة بجودة القرص المدمج. أمّا OGG فتبلغ جودة أفضل من MP3 عند معدّل البتّ نفسه وهي حرّة من قيود براءات الاختراع، ولذلك تنتشر في الألعاب والبرمجيات مفتوحة المصدر، بينما تؤدّي AAC الدور نفسه تقريباً وهي الافتراضية في أجهزة آبل ومعظم منصّات البثّ.",audio_quality_title:"التحويل لا يعيد الجودة المفقودة",audio_quality_body:"صيغ MP3 وOGG وAAC فاقدة: الترميز يتخلّص من تفاصيل لا يمكن استرجاعها. تحويل ملف MP3 بمعدّل 128 كيلوبت إلى WAV ينتج ملفاً أكبر بكثير لكنه يبدو تماماً مثل ملف الـ 128 كيلوبت، لأن التفاصيل المحذوفة ذهبت أصلاً. القاعدة العملية أن تحوّل من أفضل مصدر لديك، وأن تتجنّب إعادة الترميز المتكرّرة بين الصيغ الفاقدة، لأن كل جولة تحذف قليلاً إضافياً.",file_title:"تحويل DOCX وXLSX إلى PDF مجاناً | FrugalDomain",file_description:"حوّل مستندات وورد وإكسل إلى PDF مجاناً عبر الإنترنت. ارفع ملف DOCX أو XLSX ونزّل ملف PDF نظيفاً خلال ثوانٍ — بدون حساب وبدون علامة مائية.",file_tools:"أدوات المستندات",file_heading_a:"محوّل",file_heading_b:"الملفات",file_lede:"حوّل مستندات وورد وإكسل إلى PDF. بلا حساب، وبلا علامة مائية، وبلا انتظار.",file_why_title:"لماذا تحوّل مستنداً إلى PDF؟",file_why_body:"ملف PDF يُعرض بالشكل نفسه في كل مكان. أمّا ملف DOCX فيعتمد على الخطوط وإعدادات الصفحة ونسخة وورد على الجهاز الذي يفتحه، لذا قد يتغيّر تنسيق مستند بدا سليماً عند إرساله — سيرة ذاتية تنزاح إلى صفحتين، أو جدول تختلّ محاذاته. صيغة PDF تجمّد التنسيق كما هو.",file_expected_title:"الصيغة التي تتوقّعها المؤسسات",file_expected_body:"PDF هي الصيغة التي تطلبها معظم الجهات: طلبات التوظيف والفواتير والعقود والمعاملات الجامعية والنماذج الحكومية تشترطها عادةً، غالباً لأن أنظمتها لا تقرأ DOCX بشكل موثوق. وبالنسبة لجداول البيانات، فتحويل XLSX إلى PDF هو طريقة مشاركة أرقام يُقصد بها القراءة لا التعديل: يرى المستلم الصفوف والتنسيق كما أردتهما بالضبط، دون خطر تعديل عابر يغيّر معادلة.",file_carry_title:"ما الذي ينتقل وما الذي لا ينتقل؟",file_carry_body:"النصوص والخطوط والصور والجداول وفواصل الصفحات والتنسيق تنتقل كلها بأمانة. ما لا ينتقل هو كل ما هو تفاعلي: المعادلات في جدول البيانات تتحوّل إلى القيم المعروضة، والماكرو لا ينجو إطلاقاً. وفي جدول عريض، راجع منطقة الطباعة قبل التحويل: لملف PDF أبعاد صفحة ثابتة، لذا ستنتقل الأعمدة التي تتجاوز عرض الصفحة إلى صفحات منفصلة.",board_title:"محرّر SVG مجاني ولوح رسم متجه | FrugalDomain",board_description:"محرّر رسم متجه مجاني يعمل في متصفحك. ارسم الأشكال والمسارات، وحرّر العقد، واعمل بالطبقات، وصدّر SVG نظيفاً — بدون تثبيت وبدون حساب.",board_tools:"أدوات المتجهات",board_heading_a:"محرّر",board_heading_b:"SVG",board_lede:"ارسم الأشكال والمسارات في المتصفح وصدّرها SVG نظيفاً قابلاً للتحجيم. لا شيء لتثبّته، ولا حساب، ولا ترخيص.",board_open:"افتح لوح الرسم",board_what_title:"محرّر متجهات داخل المتصفح",board_what_body:"يعمل لوح الرسم بالأشكال والمسارات لا بالبكسلات، لذا يبقى كل ما ترسمه حادّاً بأي حجم ويُصدَّر بصيغة SVG نظيفة يمكنك وضعها مباشرة في صفحة، أو تنسيقها بـ CSS، أو تحريكها. لا شيء لتثبّته ولا ترخيص تدفع ثمنه. وهو يناسب العمل الواقع بين أداة تصميم كاملة ولقطة شاشة: رسم توضيحي للتوثيق، أو أيقونة تكمل مجموعة لديك، أو شكل تحتاجه بصيغة SVG ولم تجده في أي مكتبة.",board_why_svg_title:"لماذا SVG بدل التصدير النقطي؟",board_why_svg_body:"ملف SVG نص في جوهره. هذا يعني أنه يُضغط جيداً، ويتمدّد بلا ضبابية على أي شاشة، ويمكن تغيير لونه بقاعدة CSS واحدة، ويمكن تضمينه داخل الصفحة فلا يكلّف طلب شبكة إضافياً. أمّا ملف PNG للرسم نفسه فثابت عند حجم واحد ويحتاج ملفاً منفصلاً لكل نسخة. وSVG يبقى قابلاً للتحرير أيضاً: إعادة فتحه تعطيك المسارات والأشكال نفسها التي رسمتها، بينما التصدير النقطي سطّحها إلى بكسلات ولا يمكن تفكيكها مجدداً.",touch_title:"محاكي اللمس والإيماءات لبيانات الكتابة اليدوية | FrugalDomain",touch_description:"حاكِ إيماءات اللمس والتقط بيانات ضربات الكتابة اليدوية في المتصفح. مبني لاختبار واجهات اللمس وجمع مجموعات بيانات التدريب.",touch_tools:"أدوات المطوّرين",touch_heading_a:"محاكي",touch_heading_b:"اللمس",touch_lede:"حاكِ إيماءات اللمس والتقط بيانات ضربات الكتابة اليدوية داخل المتصفح.",touch_open:"افتح المحاكي",touch_what_title:"ما الغرض من المحاكي؟",touch_what_body:"اختبار واجهات اللمس من المكتب صعب. فالفأرة تنتج مؤشّراً واحداً دقيقاً، بينما ينتج الإصبع الحقيقي مساحة تماس عريضة ومساراً منحنياً وضغطاً متغيّراً — ولهذا قد تفشل إيماءة تعمل بلا خلل مع الفأرة على الهاتف. تولّد هذه الأداة إدخال لمس اصطناعياً حتى يمكن إنتاج تلك المسارات وإعادة تشغيلها عن قصد.",touch_data_title:"ما الذي يُسجَّل؟",touch_data_body:"تُلتقط كل ضربة كقائمة مرتّبة من النقاط مع الإحداثيات والتوقيت، وهي الصيغة نفسها التي تتوقّعها معظم نماذج التعرّف على الكتابة اليدوية والإيماءات. ولأن التوقيت محفوظ، يحمل التسجيل السرعة والإيقاع إضافةً إلى الشكل، وكلاهما مهم للمصنّف. ويمكن تصدير البيانات وإدخالها مباشرة في مسار تدريب، أو إعادة تشغيلها لإعادة إنتاج تفاعل بعينه أثناء تتبّع خلل في معالج لمس.",about_title:"من نحن — الرسالة ورؤية المنتج | FrugalDomain",about_description:"من يقف خلف FrugalDomain، ولماذا بُنيت المنصّة، وإلى أين يتّجه المنتج. تعرّف على الفريق وعلى التفكير الذي وراء الأدوات.",about_eyebrow:"من نحن",about_heading:"نبني تجارب رقمية أفضل",about_lede:"رسالتنا في FrugalDomain أن نمنح المطوّرين والمصمّمين أيقونات عالية الجودة قابلة للتخصيص وأدوات بديهية تختصر سير العمل الإبداعي.",about_vision_title:"تصميم بلا احتكاك",about_vision_body:"نؤمن بأن العثور على الأصول البصرية وتخصيصها ودمجها ينبغي أن يكون أسهل جزء في أي مشروع. وُلدت FrugalDomain من الإحباط الناتج عن إدارة حزم أيقونات متفرّقة والاعتماد على محرّرات خارجية معقّدة. هدفنا بسيط: أن نكون المصدر الوحيد لكل احتياجاتك من أيقونات SVG وتحويل الصور، عبر واجهة أنيقة مبنية على الأداء.",about_team_title:"الفريق",about_team_body:"محمد ناصر الدين — مطوّر full-stack يعمل بـ Laravel وReact، ويبني منصّات سريعة قابلة للصيانة من طرف إلى طرف: يصمّم نموذج البيانات، ويبني واجهة البرمجة، ثم يشحن الواجهة التي تستهلكها.",about_cta:"تصفّح مكتبة الأيقونات",contact_title:"تواصل معنا — الدعم واستفسارات المشاريع | FrugalDomain",contact_description:"تواصل مع FrugalDomain للدعم أو استفسارات المشاريع أو الملاحظات. راسلنا بالبريد الإلكتروني أو عبر واتساب — نردّ بالعربية والإنجليزية.",contact_eyebrow:"تواصل معنا",contact_heading:"ابقَ على تواصل",contact_lede:"أسئلة أو استفسارات عن مشروع أو ملاحظات — أرسل رسالة وتصل مباشرةً إلى صندوق الوارد. نردّ عادةً خلال 24 ساعة.",contact_email_label:"البريد الإلكتروني",contact_whatsapp_label:"واتساب",contact_location_label:"الموقع",contact_location_value:"عن بُعد — متاح عالمياً",contact_form_cta:"افتح نموذج المراسلة",faq_title:"الأسئلة الشائعة | FrugalDomain",faq_description:"إجابات عن مكتبة أيقونات FrugalDomain، وصيغ الملفات، وأدوات التخصيص، والحسابات المجانية والمدفوعة، وسياسة الاسترداد.",faq_eyebrow:"تحتاج مساعدة؟",faq_lede:"كل ما تحتاج معرفته عن مكتبة الأيقونات والمحرّر وحسابك — مجموعاً في مكان واحد.",apps_title:"معرض التطبيقات — معاينات حيّة وتوثيق | FrugalDomain",apps_description:"تطبيقات بُنيت ونُشرت على FrugalDomain. لكل تطبيق صفحة توثيق خاصة به ومعاينة حيّة تجرّبها في المتصفح قبل الدمج.",apps_eyebrow:"التطبيقات",apps_heading:"تطبيقات منشورة على FrugalDomain",apps_lede:"لكل تطبيق صفحة توثيق خاصة به ومعاينة حيّة يمكنك فتحها في المتصفح.",apps_cta:"تصفّح التطبيقات",docs_title:"التوثيق — ربط المتجر وواجهة REST | FrugalDomain",docs_description:"توثيق تقني لـ FrugalDomain: اربط متجرك، وادمج تطبيقات الهاتف، وانشر تطبيقاتك، واستخدم واجهة REST. يشمل إرشادات الأمان وحلّ المشكلات.",docs_eyebrow:"التوثيق",docs_heading:"توثيق التكامل",docs_lede:"دليل تقني للمنصّة: ربط المتاجر، ودمج تطبيقات الهاتف، ونشر تطبيقاتك الخاصة، وواجهة REST.",docs_overview_title:"نظرة عامة على المنصّة",docs_overview_body:"FrugalDomain منصّة تجمع عمليات الكتالوج والمخزون والمحتوى والطلبات في نظام واحد. تُدير بيانات متجرك من سطح تحكّم واحد، وتحتفظ بمصدر تجاري وحيد للحقيقة بدل توزيع البيانات على أدوات متفرّقة.",docs_sections_title:"ما الذي يغطّيه التوثيق؟",docs_cta:"اقرأ التوثيق الكامل (بالإنجليزية)",privacy_title:"سياسة الخصوصية | FrugalDomain",privacy_description:"كيف تجمع FrugalDomain بياناتك وتستخدمها وتخزّنها وتحميها، وما الذي لا نشاركه أبداً، وما حقوقك على معلوماتك.",privacy_heading:"سياسة الخصوصية",privacy_lede:"توضّح هذه الصفحة البيانات التي نجمعها وكيف نستخدمها. النسخة الإنجليزية هي المرجع القانوني المعتمد.",terms_title:"شروط الخدمة | FrugalDomain",terms_description:"الشروط التي تحكم استخدام FrugalDomain: ترخيص الأيقونات المنزّلة، والاستخدام المقبول، وقواعد الحسابات، والاشتراكات والاسترداد.",terms_heading:"شروط الخدمة",terms_lede:"توضّح هذه الصفحة شروط استخدام الموقع وترخيص الأصول. النسخة الإنجليزية هي المرجع القانوني المعتمد.",legal_read_en:"اقرأ النصّ القانوني الكامل بالإنجليزية",english_version:"English version",open_tool:"افتح الأداة",profile_title:"محمد ناصر الدين — مطوّر Full-Stack | FrugalDomain",profile_description:"محمد ناصر الدين مطوّر full-stack يبني واجهات خلفية بـ Laravel وواجهات أمامية بـ React. اطّلع على المهارات والخبرة وتفاصيل التواصل.",profile_lede:"مطوّر full-stack يعمل بـ Laravel وReact — يبني منصّات سريعة قابلة للصيانة من طرف إلى طرف.",profile_about_title:"نبذة",profile_about_body:"مطوّر full-stack متخصّص في بناء واجهات خلفية معيارية بـ Laravel وواجهات أمامية حديثة بـ React. أصمّم نموذج البيانات، وأبني واجهة البرمجة، ثم أشحن الواجهة التي تستهلكها — بانحياز واضح نحو البنية النظيفة والأداء المتوقَّع والشيفرة التي تبقى مقروءة.",profile_skills_title:"المهارات",profile_skills_body:"PHP وLaravel وMySQL على الخادم، وReact وReact Router وTailwind وVite في الواجهة، إضافةً إلى تصميم واجهات REST والتكامل مع أنظمة خارجية. المهارات المعروضة مستخلصة ممّا يستخدمه هذا المشروع فعلياً، لا من قائمة سيرة ذاتية عامة.",faq_q1:"ما الذي يميّز أيقونات FrugalDomain عن غيرها؟",faq_a1:"تقدّم FrugalDomain مكتبة منتقاة بعناية ومحدَّثة باستمرار من أيقونات SVG وPNG. والفرق يكمن في أدوات التخصيص المتقدّمة التي نوفّرها، والتي تتيح لك ضبط اللون والحجم وسماكة الخط بسهولة قبل التنزيل، بما يضمن اندماجاً مثالياً في مشروعك.",faq_q2:"ما صيغ الملفات المتاحة للتنزيل؟",faq_a2:"ندعم أساساً صيغة SVG للرسوم المتجهة عالية الجودة المستقلّة عن الدقّة، وصيغة PNG بأحجام متعدّدة لاحتياجات الرسوم النقطية. كما نوفّر أدوات لتحويل الصور إلى صيغ أخرى.",faq_q3:"هل أحتاج إلى حساب لتنزيل الأيقونات؟",faq_a3:"لا، يمكنك تصفّح وتنزيل كثير من أيقوناتنا القياسية دون حساب. لكن إنشاء حساب مجاني يتيح لك حفظ مجموعات أيقونات مخصّصة، وإدارة سجل التنزيلات، والوصول إلى مزايا إضافية.",faq_q4:"كيف أخصّص لون الأيقونة وحجمها؟",faq_a4:"في صفحة تفاصيل الأيقونة ستجد لوحة تحرير تفاعلية. استخدم منتقي الألوان أو حقول الإدخال لضبط قيمة HEX، واستخدم المنزلق لتحديد الحجم بالبكسل. وتُعرض التغييرات فوراً في المعاينة.",faq_q5:"هل استخدام FrugalDomain مجاني؟",faq_a5:"تقدّم FrugalDomain مستوى مجانياً غنياً يضمّ آلاف الأيقونات والوصول إلى الأدوات الأساسية. كما نوفّر اشتراك Pro للمشاريع التجارية، مع تنزيلات غير محدودة ووصول إلى حزم أيقونات وأدوات متقدّمة حصرية.",faq_q6:"ما سياسة الاسترداد لاشتراكات Pro؟",faq_a6:"نوفّر ضمان استرداد خلال 7 أيام لكل اشتراكات Pro الجديدة إن لم تكن راضياً عن المزايا. يُرجى مراجعة شروط الخدمة للتفاصيل الكاملة.",apps_what_title:"ما الذي تجده هنا؟",apps_what_body:"تطبيقات كاملة بُنيت على المنصّة ونُشرت تحت المسار الخاص بها. من بينها نظام إدارة جمعيات خيرية يغطّي التبرّعات والمستفيدين والمشاريع والمنح بمحاسبة أموال مقيَّدة، ونظام صيدليات متعدّد الفروع يعمل محلياً مع صرف الأدوية ومخزون يراعي تواريخ الصلاحية، ونظام محاسبة ومخزون ونقاط بيع يعمل على الشبكة المحلية دون إنترنت، ومنصّة إدارة مؤسسية تشمل الموظفين والفروع والأقسام والتعاميم وأرشيف الملفات.",apps_how_title:"كيف تُنشر التطبيقات؟",apps_how_body:"كل تطبيق يُستضاف كبناء مستقلّ له توجيهه الخاص، ويحصل على بطاقة في المعرض وصفحة توثيق ومعاينة حيّة. هذا يعني أنك تستطيع تجربة التطبيق في المتصفح قبل أي قرار دمج، دون تثبيت شيء.",privacy_what_title:"ما البيانات التي نجمعها؟",privacy_what_body:"نجمع الحدّ الأدنى اللازم لتشغيل الخدمة: بيانات الحساب عند التسجيل، وسجل التنزيلات والمفضّلة لمن أنشأ حساباً، وبيانات استخدام مجمّعة تساعدنا على فهم الصفحات الأكثر فائدة. الملفات التي ترفعها للتحويل تُعالَج لإنتاج النتيجة ولا تُستخدم لأي غرض آخر.",privacy_rights_title:"حقوقك",privacy_rights_body:"يمكنك طلب الاطّلاع على بياناتك أو تصحيحها أو حذف حسابك في أي وقت عبر صفحة التواصل. ولا نبيع البيانات الشخصية ولا نشاركها مع أطراف ثالثة لأغراض تسويقية.",terms_use_title:"الاستخدام المقبول",terms_use_body:"الأدوات متاحة للاستخدام الشخصي والتجاري. ما هو غير مسموح به هو إساءة استخدام الخدمة بما يضرّ بتوافرها للآخرين، أو محاولة الوصول إلى حسابات أو بيانات لا تخصّك، أو إعادة توزيع مكتبة الأيقونات نفسها كحزمة باسمك.",terms_license_title:"ترخيص الأصول",terms_license_body:"الأيقونات التي تنزّلها حرّة الاستخدام في الأعمال الشخصية والتجارية دون الحاجة إلى نسب الفضل. يمكنك تعديلها وشحنها داخل منتج تبيعه. أمّا إعادة توزيع المجموعة نفسها كمنتج مستقلّ فهي الاستخدام الوحيد غير المشمول.",terms_accounts_title:"الحسابات والاشتراكات",terms_accounts_body:"إنشاء الحساب اختياري ويضيف حفظ المفضّلة وسجل التنزيلات ومجموعات مخصّصة. ولاشتراكات Pro الجديدة ضمان استرداد خلال 7 أيام إن لم تكن راضياً عن المزايا.",contact_how_title:"كيف نتواصل؟",contact_how_body:"أسرع طريقة هي البريد الإلكتروني أو واتساب — كلاهما يصل مباشرةً دون وسيط. نردّ عادةً خلال 24 ساعة، بالعربية أو بالإنجليزية حسب لغة رسالتك. وإن كان استفسارك عن مشروع، فذكر النطاق التقريبي والمدّة الزمنية المتوقّعة يختصر جولة أسئلة كاملة.",contact_what_title:"ما الذي نساعد فيه؟",contact_what_body:"الدعم التقني لأدوات الموقع، والاستفسارات عن تطوير مشاريع بـ Laravel وReact، والملاحظات على المكتبة أو الأدوات. إن وجدت خللاً أو أيقونة لا تعمل كما يجب، فالإبلاغ عنه يساعدنا فعلاً — معظم التحسينات جاءت من ملاحظات المستخدمين."},t={"jpg-to-png":{title:"تحويل JPG إلى PNG — مجاناً وبلا تسجيل | FrugalDomain",description:"حوّل صور JPG إلى PNG مجاناً. احصل على جودة بلا فقدان ودعم الشفافية بنقرتين — بدون حساب وبدون علامة مائية وبدون حدّ على الرفع.",lede:"حوّل صورة JPG إلى PNG بلا فقدان في الجودة، بنقرتين. بلا حساب، وبلا علامة مائية، وبلا انتظار.",body:["تستخدم صيغة JPG ضغطاً فاقداً: كل عملية حفظ تتخلّص من قدر صغير من التفاصيل لتصغير الملف، والخسارة تتراكم مع كل إعادة ترميز. أمّا PNG فبلا فقدان، لذا يجمّد التحويل إليها الصورة على حالها الحالية تماماً. هذا يجعل PNG الوجهة الصحيحة حين تنوي تعديل الصورة مراراً، أو حين تحتاج نسخة أصلية نظيفة تصدّر منها أحجاماً أخرى.","السبب الثاني للتحويل هو الشفافية. لا تملك JPG قناة ألفا، وتملأ أي منطقة شفافة بالأبيض الصريح، ولهذا يظهر الشعار المحفوظ بصيغة JPG داخل مربّع أبيض. تحتفظ PNG بقناة ألفا، فبعد التحويل يمكنك محو الخلفية وستبقى الشفافية سليمة.","ما لا يستطيع التحويل فعله هو استعادة تفاصيل أتلفها ضغط JPG سابقاً. إذا كانت الصورة الأصلية تُظهر تكتّلاً أو هالات حول الحواف الحادّة، فهذه التشوّهات جزء من الصورة وستُنقل بأمانة إلى ملف PNG. حوّل دائماً من أعلى نسخة JPG جودة لديك، لا من نسخة أُعيد حفظها مرّات عديدة."],faq:[{question:"هل يحسّن التحويل من JPG إلى PNG جودة الصورة؟",answer:"لا. التحويل إلى PNG يوقف أي فقدان إضافي، لكنه لا يستعيد التفاصيل التي تخلّص منها ضغط JPG من قبل. ستبدو صورة PNG مطابقة تماماً لملف JPG الذي بدأت منه — والفائدة أن تعديلها وإعادة حفظها بعد ذلك لن يكلّفك شيئاً من الجودة."},{question:"هل سيكون ملف PNG أكبر من JPG؟",answer:"غالباً نعم، وأحياناً بعدّة أضعاف. صيغة PNG بلا فقدان، لذا لا يمكنها بلوغ الأحجام التي تحقّقها JPG عبر التخلّص من التفاصيل. تضغط PNG الألوان المسطّحة والحواف الحادّة بكفاءة، فتبقى الشعارات ولقطات الشاشة معقولة الحجم، بينما تتضخّم الصور الفوتوغرافية أكثر من غيرها."},{question:"هل أحصل على خلفية شفافة بمجرّد التحويل إلى PNG؟",answer:"التحويل يمنح الملف قناة ألفا، لكنه لا يزيل الخلفية نيابةً عنك. فملف JPG قد سطّح أي شفافية إلى لون صريح مسبقاً، لذا تحوّل أولاً إلى PNG ثم تمحو الخلفية في برنامج تحرير — وستبقى الشفافية محفوظة من تلك اللحظة فصاعداً."}]},"png-to-jpg":{title:"تحويل PNG إلى JPG — مجاناً وبلا تسجيل | FrugalDomain",description:"حوّل صور PNG إلى JPG مجاناً وقلّص حجم الملف بشكل كبير. مثالي للصور الفوتوغرافية ومرفقات البريد وحدود الرفع — بدون حساب وبدون علامة مائية.",lede:"حوّل ملف PNG الثقيل إلى JPG مضغوط. بلا حساب، وبلا علامة مائية، وبلا انتظار.",body:["تخزّن PNG كل بكسل دون فقدان، ولهذا تكون الصور الفوتوغرافية المحفوظة بها أكبر بعدّة أضعاف ممّا تحتاج. أمّا الضغط الفاقد في JPG فمصمّم للمحتوى الفوتوغرافي — التدرّجات الناعمة والألوان المتّصلة — وعادةً ما يقلّص الملف إلى جزء صغير من حجمه دون فرق تلاحظه عند العرض الطبيعي.","هذا هو التحويل الذي تلجأ إليه حين يرفض نموذج رفع ملفك لأنه كبير، أو حين يرتدّ مرفق بريد إلكتروني، أو حين يهمّك وزن الصفحة عند التحميل. وتحويل معرض من الصور الفوتوغرافية بصيغة PNG إلى JPG هو عادةً أكبر توفير منفرد متاح في صفحة بطيئة.","المقابل هو الشفافية. لا تملك JPG قناة ألفا، لذا تُدمج أي منطقة شفافة فوق خلفية صريحة — بيضاء ما لم تُحدَّد غير ذلك. أبقِ الشعارات والأيقونات وكل ما له خلفية مقصوصة بصيغة PNG، أو حوّلها إلى WebP بدلاً من ذلك، فهي تحافظ على الشفافية مع ضغط قوي."],faq:[{question:"هل يقلّل التحويل من PNG إلى JPG جودة الصورة؟",answer:"قليلاً، وهذا مقصود في التصميم. تتخلّص JPG من التفاصيل التي يصعب على العين ملاحظتها لتصغير الملف. في الصور الفوتوغرافية يكون الفرق غير مرئي عادةً بالأحجام المعتادة، أمّا في النصوص والرسوم الخطّية والحواف الحادّة فيظهر على شكل هالات خفيفة، ولذلك يُفضّل إبقاء تلك الصور بصيغة PNG."},{question:"ماذا يحدث للشفافية عند التحويل إلى JPG؟",answer:"تُفقد. لا تملك JPG قناة ألفا، لذا تُملأ البكسلات الشفافة بلون صريح، أبيض في العادة. إن كنت تحتاج الشفافية وصغر الحجم معاً، فحوّل إلى WebP بدلاً من JPG."},{question:"كم سيصغر حجم ملف JPG؟",answer:"في الصور الفوتوغرافية، عادةً أصغر بخمس إلى عشر مرّات من PNG. أمّا في الرسوم المسطّحة والشعارات ولقطات الشاشة فالتوفير أقل بكثير، وقد تكون PNG هي الأصغر فعلاً، لأنها تضغط المساحات الواسعة ذات اللون الموحّد بكفاءة عالية."}]},"png-to-webp":{title:"تحويل PNG إلى WebP — مجاناً وبلا تسجيل | FrugalDomain",description:"حوّل PNG إلى WebP مجاناً وقلّص وزن الصور بنحو 30% مع الحفاظ على الشفافية. صفحات أسرع ومؤشرات أداء أفضل — بدون حساب.",lede:"قلّص وزن الصور مع الحفاظ على الشفافية. بلا حساب، وبلا علامة مائية، وبلا انتظار.",body:["صُمّمت WebP لتحلّ محلّ PNG وJPG معاً على الويب. فهي تدعم الضغط بلا فقدان وقناة ألفا مثل PNG، لكنها ترمّزهما بكفاءة أعلى بكثير — أصغر بنحو 26% من ملف PNG المكافئ في المتوسط، وأكثر من ذلك في الصور ذات المساحات المسطّحة الواسعة.","هذا الفارق في الحجم هو سبب ظهور هذا التحويل في تقارير قياس الأداء. فالصور عادةً أثقل ما في الصفحة، وغالباً ما يكون أكبر عنصر مرئي فيها صورة، لذا يُعدّ تحويل ملفات PNG إلى WebP من التغييرات القليلة التي تحسّن مؤشرات الأداء الأساسية دون المساس بشيفرة التطبيق.","دعم المتصفحات لم يعد مصدر قلق: كل المتصفحات الحديثة تعرض WebP، بما فيها سفاري منذ الإصدار 14. وإن كنت ما تزال بحاجة إلى دعم أجهزة قديمة فعلاً، فقدّم WebP داخل عنصر picture مع مصدر بديل بصيغة PNG، وسيختار المتصفح ما يستطيع عرضه."],faq:[{question:"هل تحافظ WebP على الشفافية مثل PNG؟",answer:"نعم. تدعم WebP قناة ألفا كاملة، لذا تبقى الخلفيات الشفافة سليمة بعد التحويل. وهذا هو السبب الرئيسي لاختيار WebP بدل JPG حين تحتاج ملفاً أصغر دون التضحية بالشفافية."},{question:"كم تصغر WebP مقارنةً بـ PNG؟",answer:"أصغر بنحو 26% في المتوسط في الوضع بلا فقدان، وأكثر من ذلك بكثير في الصور ذات المساحات الواسعة من اللون المسطّح مثل الشعارات ولقطات الشاشة وصور الواجهات. أمّا المحتوى الفوتوغرافي المحفوظ بوضع WebP الفاقد فيصغر أكثر من ذلك بكثير."},{question:"هل تدعم كل المتصفحات صيغة WebP؟",answer:"نعم، كل المتصفحات الحديثة تعرض WebP، بما فيها سفاري من الإصدار 14 فصاعداً. وللأجهزة القديمة جداً، قدّم ملف WebP داخل عنصر picture إلى جانب مصدر PNG ليتراجع المتصفح إليه تلقائياً."}]},"webp-to-png":{title:"تحويل WebP إلى PNG — مجاناً وبلا تسجيل | FrugalDomain",description:"حوّل صور WebP إلى PNG مجاناً. احصل على صيغة يقبلها كل برنامج وكل تطبيق، مع الحفاظ على الشفافية — بدون حساب وبدون علامة مائية.",lede:"حوّل ملف WebP إلى PNG يفتحه أي برنامج. بلا حساب، وبلا علامة مائية، وبلا انتظار.",body:["صيغة WebP ممتازة على الويب ومربكة في كل مكان آخر. فكثير من برامج سطح المكتب وأدوات التصميم الأقدم ومحرّرات المستندات ونماذج الرفع في المنصّات ما تزال ترفضها، ولهذا كثيراً ما يحتاج ملف حفظته من موقع إلى تحويل قبل أن تتمكّن من استخدامه.","وPNG هي أكثر وجهة أماناً. فهي بلا فقدان، أي لا شيء يتدهور أثناء التحويل، وتحتفظ بقناة ألفا، فيبقى ملف WebP ذو الخلفية الشفافة شفافاً بعد تحويله إلى PNG.","توقّع أن يكون ملف PNG أكبر بوضوح — وهذا ببساطة ثمن الضغط الأقدم والأقل كفاءة في PNG. إن كان الملف عائداً إلى موقع ويب على أي حال فالأفضل إبقاؤه بصيغة WebP؛ وحوّل إلى PNG حين يعجز شيء في سير عملك عن قراءة WebP أصلاً."],faq:[{question:"لماذا لا يفتح برنامجي ملفات WebP؟",answer:"WebP صيغة صُمّمت للويب أولاً، وكثير من تطبيقات سطح المكتب والمحرّرات الأقدم ونماذج الرفع لم تضف دعمها يوماً. التحويل إلى PNG يمنحك ملفاً يفتحه كل شيء تقريباً، دون أي خسارة في جودة الصورة."},{question:"هل يفقد التحويل من WebP إلى PNG شيئاً من الجودة؟",answer:"لا. صيغة PNG بلا فقدان، لذا يحافظ التحويل على الصورة كما هي في ملف WebP تماماً. وإذا كان ملف WebP نفسه محفوظاً بضغط فاقد، فستُنقل تشوّهاته الموجودة بأمانة — فالتحويل لا يضيف تشوّهات ولا يزيلها."},{question:"هل تبقى الشفافية بعد التحويل من WebP إلى PNG؟",answer:"نعم. كلتا الصيغتين تدعمان قناة ألفا، لذا تبقى المناطق الشفافة في ملف WebP شفافة في ملف PNG الناتج."}]},"jpg-to-webp":{title:"تحويل JPG إلى WebP — مجاناً وبلا تسجيل | FrugalDomain",description:"حوّل JPG إلى WebP مجاناً وقلّص حجم الصور الفوتوغرافية بنحو 25-35% بنفس الجودة المرئية. صفحات أسرع بدون حساب وبدون علامة مائية.",lede:"قلّص حجم الصور للويب دون تراجع ملحوظ في الجودة. بلا حساب، وبلا علامة مائية، وبلا انتظار.",body:["يضغط الوضع الفاقد في WebP الصور الفوتوغرافية بنحو 25-35% أصغر من JPG عند جودة مرئية مماثلة. وفي صفحة مليئة بالصور يمثّل ذلك خفضاً كبيراً في الوزن الإجمالي دون فرق محسوس على الشاشة.","وهو أحد التوصيات القياسية في أدوات قياس الأداء مثل PageSpeed Insights وLighthouse، التي تشير إلى ملفات JPG بوصفها صوراً يمكن تقديمها بصيغ أحدث، تحديداً لأن هذا التحويل متاح عادةً ويستحق العناء غالباً.","احتفظ بملفات JPG الأصلية. فـ WebP هي ما تقدّمه للزوّار، لا ما تؤرشفه: إعادة ترميز ملف JPG فاقد أصلاً إلى WebP فاقد تراكم الضغط فوق الضغط، لذا ولّد WebP دائماً من أفضل نسخة أصلية لديك، لا من ملف سبق تحويله عدّة مرّات."],faq:[{question:"هل WebP أفضل من JPG للصور الفوتوغرافية؟",answer:"لتقديم الصور على الويب، نعم عموماً: تبلغ WebP الجودة المُدركة نفسها بحجم أصغر بنحو 25-35%. لكن JPG تبقى أوسع دعماً خارج المتصفح، لذا ما تزال الخيار الأأمن للملفات التي سترسلها إلى أشخاص آخرين أو تفتحها ببرامج قديمة."},{question:"هل يفقد التحويل من JPG إلى WebP شيئاً من الجودة؟",answer:"كلتاهما صيغة فاقدة، لذا تكلّف إعادة الترميز شيئاً يسيراً دائماً. وعند إعدادات الجودة المعتادة لا يكون الفرق مرئياً بالأحجام الطبيعية. حوّل من أعلى نسخة أصلية جودة لديك، لا من ملف JPG أُعيد حفظه مراراً."},{question:"هل أحذف ملف JPG الأصلي بعد التحويل؟",answer:"لا. احتفظ بملف JPG كنسخة أرشيفية وقدّم ملف WebP للزوّار. وإن احتجت لاحقاً حجماً أو صيغة مختلفة، فتوليدها من الأصل يجنّبك تراكم جولة ضغط فاقد فوق أخرى."}]},"png-to-gif":{title:"تحويل PNG إلى GIF — مجاناً وبلا تسجيل | FrugalDomain",description:"حوّل صور PNG إلى GIF مجاناً. مفيد للأنظمة القديمة والرسوم البسيطة التي تحتاج توافقاً واسعاً — بدون حساب وبدون علامة مائية.",lede:"حوّل ملف PNG إلى GIF من أجل الأماكن التي ما تزال تشترطها. بلا حساب، وبلا علامة مائية، وبلا انتظار.",body:["تقتصر صيغة GIF على لوحة من 256 لوناً، لذا يعني تحويل ملف PNG كامل الألوان أن كل لون سيُربط بأقرب مدخل متاح في اللوحة. الرسوم المسطّحة والشعارات البسيطة والرسوم الخطّية تنجو من ذلك جيداً؛ أمّا الصور الفوتوغرافية والتدرّجات الناعمة فتُظهر عادةً تدرّجاً مقطّعاً واضحاً.","وشفافيتها أيضاً إمّا كاملة أو معدومة: فالبكسل إمّا معتم تماماً أو شفاف تماماً، بلا ألفا جزئية. لذا فالظلال الناعمة والحواف المنعّمة التي كانت تتلاشى تدريجياً في ملف PNG ستتحوّل إلى حدود حادّة ومسنّنة في ملف GIF.","في كل سياق حديث تقريباً تكون PNG أو WebP هي الصيغة الأفضل. حوّل إلى GIF حين يطلبها شيء ما تحديداً — نظام قديم، أو منصّة لا تقبل غيرها، أو سير عمل مبني حول ملفات GIF."],faq:[{question:"لماذا تبدو صورتي أسوأ بصيغة GIF؟",answer:"تدعم GIF 256 لوناً فقط لكل صورة. وتحويل ملف PNG كامل الألوان يجبر كل لون على أقرب مدخل في اللوحة، فيظهر ذلك على شكل تدرّج مقطّع عبر المساحات الناعمة. والرسوم ذات الألوان المسطّحة تتأثر أقل بكثير من الصور الفوتوغرافية."},{question:"هل تدعم GIF الشفافية؟",answer:"بشكل كامل أو معدوم فقط — لا توجد شفافية جزئية. فالظلال الناعمة والحواف المنعّمة التي كانت تتلاشى تدريجياً في PNG تصبح حادّة الحواف في GIF، وهذا أشيع سبب لظهور الشعارات المحوّلة مسنّنة."},{question:"هل أستخدم GIF أم PNG؟",answer:"PNG في جميع الحالات تقريباً: ألوان أكثر، وشفافية ألفا حقيقية، وحجم أصغر عادةً. لا تختر GIF إلا حين يشترط نظام بعينه هذه الصيغة ولا يقبل سواها."}]}},a={tools:{crumb:"أدوات المطوّرين",name:"أدوات المطوّرين من FrugalDomain",title:"أدوات المطوّرين — التوكنات وملفات الوكلاء وJSON والنص العربي | FrugalDomain",description:"أدوات مجانية تعمل داخل المتصفح: حاسبة التوكنات والتكلفة عبر سبعة مزوّدين، ومولّد AGENTS.md، ومدقّق JSONL للتدريب، وأدوات النص العربي وJSON وSVG والأيقونات.",eyebrow:"أدوات المطوّرين",heading:"أدوات تؤدي ",headingAccent:"مهمّة واحدة",lede:"بلا حسابات، وبلا رفع للملفات، وبلا مهلة تجريبية. كل أداة هنا تعمل داخل التبويب وتؤدي مهمّة واحدة كنت ستجمعها من ثلاثة مستودعات نصف مهجورة.",cta:{to:"/tools",label:"افتح قائمة الأدوات"},sections:[{title:"داخل المتصفح، لا على خادم",body:["كل أداة هنا تؤدي عملها داخل التبويب. لا شيء تلصقه أو تسحبه إليها يُرفع إلى أي مكان، ولهذا لا يوجد حساب ولا حصّة استخدام — ببساطة لا يوجد ما يُقاس أو يُحاسب عليه.","وهذا ما يجعلها صالحة للبيانات التي لا يمكنك لصقها في أداة مستضافة: مفتاح في ملف إعدادات، أو استجابة حقيقية من واجهة برمجية، أو مجموعة تدريب هي على الأرجح أكثر ملفات مشروعك حساسية."]},{title:"أرقام مؤرَّخة ومصدرها معلوم",body:["حين تذكر أداة رقماً — سعر نموذج، أو حجم نافذة سياق — فإنها تذكر تاريخ التحقق منه وتربط الصفحة التي جاء منها. الرقم الواثق بلا مصدر هو العطب المعتاد في أدوات من هذا النوع، وأسعار النماذج تتغيّر دون إشعار."]},{title:"العربية ليست إضافة لاحقة",body:["العربية متعامَل معها هنا عن قصد لا بالمصادفة: تقدير التوكنات يحتسب كم هي أقل كفاءة في الترميز من الإنجليزية، وأداة كاملة وُجدت لتهيئتها للفهرسة والتدريب، ومولّد البيانات الوهمية ينتج أسماء ومدناً عربية حقيقية، والتخطيطات تنعكس انعكاساً صحيحاً من اليمين إلى اليسار."]}],faq:[{question:"هل هذه الأدوات مجانية؟",answer:"نعم، جميعها، بلا حساب وبلا فترة تجريبية وبلا حصّة استخدام. لا يوجد ما يُقاس لأن الأدوات تؤدي عملها داخل تبويب المتصفح لا على خادم."},{question:"هل يُرفع ما ألصقه إلى خادم؟",answer:"لا. كل أداة هنا تعمل داخل المتصفح. الموجّه الذي تحسب تكلفته، وملف JSON الذي تصحّحه، ومجموعة البيانات التي تدقّقها — كلها تبقى في التبويب، ولهذا يمكن استخدامها على بيانات لا يصحّ لصقها في أداة مستضافة."},{question:"هل تدعم الأدوات اللغة العربية؟",answer:"نعم، وبشكل مقصود. تقدير التوكنات يحتسب ضعف كفاءة ترميز العربية، وهناك أداة مخصّصة لتطبيع النص العربي، ومولّد البيانات الوهمية ينتج أسماء ومدناً عربية حقيقية، وواجهات الأدوات كلها تعمل من اليمين إلى اليسار."},{question:"من أين تأتي الأرقام المذكورة في هذه الصفحات؟",answer:"حين تذكر أداة رقماً — سعر نموذج أو حجم نافذة سياق — فإنها تذكر تاريخ التحقق منه وتربط الصفحة التي جاء منها، لأن هذه الأرقام تتغيّر دون إشعار."}],related:[{to:"/ar/IconsGalary",label:"مكتبة أيقونات SVG مجانية"},{to:"/ar/ImageConvert",label:"تحويل الصور"},{to:"/ar/vector-editor",label:"محرر الرسوم المتجهة"}]},"token-calculator":{crumb:"حاسبة التوكنات والتكلفة",features:["تقدير التوكنات عبر Anthropic وOpenAI وGoogle وxAI وDeepSeek وMistral والنماذج مفتوحة الأوزان","التكلفة لكل استدعاء والتكلفة الشهرية المتوقّعة","التحقّق من الاتّساع في نافذة السياق","تقدير يحتسب العربية على حدة","كل سعر مربوط بمصدره وتاريخ التحقّق منه"],name:"حاسبة التوكنات والتكلفة من FrugalDomain",title:"حاسبة التوكنات والتكلفة — Claude وGPT وGemini وأكثر | FrugalDomain",description:"قدّر عدد توكنات أي نص وتكلفته عبر ثلاثين نموذجاً من سبعة مزوّدين. تحتسب العربية على حدة لأنها تستهلك توكنات أكثر، وتعمل داخل المتصفح بلا حساب.",eyebrow:"للمطوّرين مع الذكاء الاصطناعي",heading:"كم يكلّف ",headingAccent:"هذا الموجّه؟",lede:"الصق نصاً لترى تقديراً لعدد توكناته، وهل يتّسع في نافذة سياق النموذج، وكم يكلّف في الاستدعاء الواحد وفي الشهر — عبر كل مزوّد رئيسي لا واحد فقط. والعربية محسوبة على حدة لأن المرمّزات تتعامل معها بشكل مختلف تماماً.",cta:{to:"/token-calculator",label:"افتح الحاسبة"},sections:[{title:"لماذا تقدير لا عدّ دقيق",body:["العدّ الدقيق يحتاج مفردات المرمّز الخاص بالنموذج نفسه — عشرات الآلاف من المدخلات — ولكل مزوّد مفرداته المختلفة. تحميلها كلها إلى تبويب متصفح سيكلّف أكثر من الصفحة ذاتها.","لذا تقرأ هذه الصفحة تركيب الأحرف وتقدّر منه، وتذكر لك هامش الخطأ صراحةً. وهذا يكفي تماماً لاختيار نموذج أو لتقدير ميزانية ميزة، ولا يكفي للفوترة — ولهذا تجد على الصفحة مقتطفات للعدّ الدقيق عبر واجهات Anthropic وOpenAI وGoogle وأي واجهة متوافقة مع OpenAI."]},{title:"لماذا تكلّف العربية أكثر",body:["بُنيت معظم مفردات المرمّزات على نصوص إنجليزية في الأساس، فتتفتّت الكلمة العربية إلى عدّة أجزاء، وكثيراً ما تكلّف كل علامة تشكيل توكناً كاملاً بذاتها.","النتيجة أن الفقرة نفسها قد تكلّف أكثر بنحو خمسين بالمئة بالعربية منها بالإنجليزية. هذه الصفحة تحتسب العربية على حدة بدل تطبيق نسبة إنجليزية عليها، وهو الفرق بين تقدير ميزانية صحيح وآخر بعيد تماماً."]}],faq:[{question:"كم عدد التوكنات في نصّي؟",answer:"الصق النص وسيظهر التقدير أثناء الكتابة مع هامش دقّته. تقريباً، يبلغ النص الإنجليزي نحو أربعة أحرف لكل توكن، لكن الشيفرة والنصوص كثيفة الترقيم والعربية كلها تكسر هذه النسبة — ولهذا تقيس الصفحة تركيب الأحرف بدل القسمة على أربعة."},{question:"لماذا هو تقدير وليس عدّاً دقيقاً؟",answer:"العدّ الدقيق يتطلّب مفردات المرمّز الخاص بالنموذج المحدّد، ولكل مزوّد مفرداته. التقدير هنا يقرأ تركيب الأحرف ويذكر هامشه، وهو كافٍ لاختيار نموذج أو تقدير ميزانية. وللعدّ الدقيق تجد على الصفحة مقتطفات جاهزة لواجهات المزوّدين."},{question:"لماذا تستهلك العربية توكنات أكثر من الإنجليزية؟",answer:"لأن مفردات المرمّزات بُنيت أساساً على نصوص إنجليزية، فتتفتّت الكلمة العربية إلى عدّة أجزاء وتكلّف علامات التشكيل توكناً لكل منها غالباً. الفقرة نفسها قد تكلّف أكثر بنحو خمسين بالمئة بالعربية."},{question:"هل الأسعار المعروضة محدَّثة؟",answer:"كل سعر على الصفحة يحمل تاريخ آخر تحقّق منه ورابطاً إلى صفحة التسعير عند المزوّد نفسه. أسعار النماذج تتغيّر دون إشعار، فاعتبر الرقم صحيحاً حتى ذلك التاريخ وتابع الرابط قبل اعتماد ميزانية."}],related:[{to:"/ar/tools",label:"كل أدوات المطوّرين"},{to:"/ar/arabic-text",label:"أدوات النص العربي"},{to:"/ar/jsonl-validator",label:"مدقّق JSONL للتدريب"}]},"agents-md":{crumb:"مولّد AGENTS.md",features:["صيغ AGENTS.md وCLAUDE.md و.cursorrules وتعليمات Copilot","إعدادات جاهزة للحزم التقنية الشائعة","حقول أوامر التثبيت والاختبار والبناء والفحص","عدد توكنات الملف المولَّد","نسخ أو تنزيل بلا حساب"],name:"مولّد AGENTS.md من FrugalDomain",title:"مولّد AGENTS.md — تعليمات وكلاء البرمجة | FrugalDomain",description:"ولّد ملف AGENTS.md أو CLAUDE.md أو .cursorrules أو تعليمات Copilot لمستودعك. أجب عن بضعة أسئلة عن حزمتك وأوامرك، ثم انسخ الملف.",eyebrow:"للمطوّرين مع الذكاء الاصطناعي",heading:"الملف الذي يقرأه ",headingAccent:"وكيل البرمجة",lede:"الملف الذي يقرأه وكيل البرمجة حين يفتح مستودعك. أجب عمّا لا يستطيع استنتاجه بنفسه — مدير الحزم، وأمر الاختبارات، وما يجب ألّا يلمسه — ثم خذ الملف بالصيغة التي تتوقّعها أداتك.",cta:{to:"/agents-md",label:"افتح المولّد"},sections:[{title:"ما الذي ينتمي إلى هذا الملف",body:["الحقائق التي لا يستطيع الوكيل استنتاجها بقراءة الشيفرة وحدها: أي مدير حزم تستخدم، وأمر الاختبارات بالضبط، وأي المجلدات مولَّدة وستُكتب فوقها، وأي واجهة لا يجوز تغيير شكلها. أمّا ما يستطيع رؤيته بنفسه فذكره إهدار لنافذة السياق."]},{title:"ما الذي يجب استبعاده",body:["عبارات مثل «اكتب شيفرة نظيفة» أو «اتّبع أفضل الممارسات» أو «استخدم أسماء ذات معنى». هذه تكلّف توكنات في كل جلسة ولا تغيّر شيئاً، فلم يكن أي وكيل على وشك كتابة شيفرة رديئة عن عمد.","القاعدة التي تستحق الكتابة هي القاعدة التي وصفت خطأً وقع فعلاً. وبما أن الملف يُقرأ في كل جلسة، فطوله كلفة متكرّرة لا كلفة تُدفع مرّة — ولهذا يعرض المولّد عدد توكنات الملف أسفله. مئتا سطر نافع خير من ألف سطر متحفّظ، والقاعدة التي لم تعد صحيحة يجب حذفها لا تركها لتضلّل."]}],faq:[{question:"ما هو ملف AGENTS.md؟",answer:"هو ملف Markdown في جذر المستودع يخبر وكيل البرمجة كيف يعمل داخله: أي مدير حزم يستخدم، وأمر الاختبارات بالضبط، وأي المجلدات مولَّدة، وما الذي يجب ألّا يلمسه. يقرأه الوكيل في بداية الجلسة كما يقرأ زميل جديد دليل المساهمة."},{question:"ماذا أكتب في ملف AGENTS.md؟",answer:"فقط ما لا يستطيع الوكيل استنتاجه من الشيفرة: مدير الحزم، وأمر الاختبارات الحقيقي، والمجلدات المولَّدة التي ستُكتب فوقها، والواجهة التي لا يجوز تغيير شكلها. كل ما عدا ذلك يراه بنفسه."},{question:"ما الذي يجب ألّا أكتبه فيه؟",answer:"التعليمات العامة مثل «اكتب شيفرة نظيفة» أو «اتّبع أفضل الممارسات». تكلّف توكنات في كل جلسة ولا تغيّر شيئاً. القاعدة التي تستحق الكتابة هي التي تصف خطأً وقع فعلاً."},{question:"هل AGENTS.md هو نفسه CLAUDE.md أو .cursorrules؟",answer:"المحتوى متقارب إلى حد بعيد، والاختلاف في اسم الملف وبعض الأعراف الخاصة بكل أداة. اختر الصيغة التي تتوقّعها أداتك من أعلى الصفحة وسيُخرج المولّد الملف وفقها، فتنتج الإجابات نفسها أيّاً من الصيغ الأربع تحتاج."}],related:[{to:"/ar/tools",label:"كل أدوات المطوّرين"},{to:"/ar/token-calculator",label:"حاسبة التوكنات والتكلفة"},{to:"/ar/jsonl-validator",label:"مدقّق JSONL للتدريب"}]},"jsonl-validator":{crumb:"مدقّق JSONL",features:["أخطاء تحليل JSON لكل سطر","فحص الأدوار وبنية الرسائل","كشف الأمثلة المكرّرة بالمحتوى","عدد التوكنات لكل مثال","يعمل داخل المتصفح ولا تُرفع البيانات"],name:"مدقّق JSONL للضبط الدقيق من FrugalDomain",title:"مدقّق JSONL لبيانات الضبط الدقيق — تحقّق قبل الرفع | FrugalDomain",description:"دقّق ملف JSONL للضبط الدقيق سطراً سطراً: أخطاء JSON، والأدوار الناقصة، والمحتوى الفارغ، والأمثلة المكرّرة، وعدد التوكنات لكل مثال. يعمل داخل المتصفح ولا تُرفع بياناتك.",eyebrow:"للمطوّرين مع الذكاء الاصطناعي",heading:"تحقّق من بيانات التدريب ",headingAccent:"قبل الرفع",lede:"افحص ملف التدريب قبل الرفع لا بعده: الأسطر المعطوبة، والأدوار التي لا يقبلها أي مدرّب، والأمثلة التي لا شيء فيها ليتعلّمه النموذج، والمكرّرات، وكم يكلّف كل مثال من التوكنات فعلاً. مجموعة بياناتك لا تغادر هذا التبويب.",cta:{to:"/jsonl-validator",label:"افتح المدقّق"},sections:[{title:"لماذا قبل الرفع لا بعده",body:["مهمّة التدريب تفشل بعد الرفع وبعد الانتظار في الطابور، ثم يشير الخطأ إلى رقم سطر في ملف لم يعد المطوّر يراه أمامه. كل فحص هنا هو أحد تلك الإخفاقات، منقولاً إلى ما قبل الرفع حيث لا يكلّف إصلاحه شيئاً."]},{title:"خطأ أم تحذير",body:["الخطأ هو ما يوقف الرفع أصلاً: سطر ليس JSON صالحاً، أو سطر ليس كائناً، أو مصفوفة رسائل فارغة، أو دور ناقص أو غير معروف، أو محتوى فارغ، أو مثال بلا دور مساعد — وهو مثال لا شيء فيه ليتعلّمه النموذج.","أمّا التحذير فهو ما يختلف المزوّدون بشأنه: أدوار الأدوات والمطوّر، ودوران متتاليان من الجهة نفسها، ومثال لا ينتهي بدور المساعد، والأمثلة القصيرة جداً. هذه تُدرَّب فعلاً، لكنها تعني عادةً أن سكربت التصدير أخطأ في مكان ما."]}],faq:[{question:"لماذا فشل رفع ملف الضبط الدقيق؟",answer:"في الغالب بسبب سطر واحد من بين آلاف: سطر ليس JSON صالحاً، أو ليس كائناً، أو مصفوفة رسائل فارغة، أو دور ناقص أو غير معروف، أو محتوى فارغ، أو مثال بلا دور مساعد. يذكر لك المزوّد رقم سطر في ملف لم تعد تراه، ولهذا يستحق الفحص المسبق دقيقة واحدة من وقتك."},{question:"ما الفرق بين الخطأ والتحذير هنا؟",answer:"الخطأ يوقف الرفع أصلاً. أمّا التحذير فهو ما يختلف المزوّدون بشأنه: أدوار الأدوات والمطوّر، أو دوران متتاليان من الجهة نفسها، أو مثال لا ينتهي بدور المساعد، أو مثال قصير جداً. التحذيرات تُدرَّب، لكنها عادةً علامة على خلل في سكربت التصدير."},{question:"لماذا تهمّ الأمثلة المكرّرة؟",answer:"المثال المكرّر يُدرَّب عليه مرّتين، فيتضاعف وزنه بهدوء أمام بقية المجموعة. المكرّرات تأتي عادةً من إعادة تشغيل سكربت تصدير لا عن قصد، ولهذا تُكتشف هنا بمقارنة المحتوى لا بأرقام الأسطر."},{question:"هل تُرفع بيانات التدريب إلى أي مكان؟",answer:"لا. يُقرأ الملف ويُفحص داخل تبويب المتصفح ولا يُرسل شيء إلى خادم. وهذا مقصود: مجموعة الضبط الدقيق هي عادةً أكثر ملفات المشروع حساسية."}],related:[{to:"/ar/tools",label:"كل أدوات المطوّرين"},{to:"/ar/token-calculator",label:"حاسبة التوكنات والتكلفة"},{to:"/ar/arabic-text",label:"أدوات النص العربي"}]},"arabic-text":{crumb:"أدوات النص العربي",features:["حذف التشكيل والتطويل","توحيد الألف والياء والهمزة","تحويل الأرقام العربية-الهندية إلى غربية","كشف المحارف غير المرئية ومحارف الاتجاه بالاسم والعدد","يعمل داخل المتصفح"],name:"أدوات النص العربي من FrugalDomain",title:"أدوات النص العربي — تطبيع العربية للفهرسة والتدريب | FrugalDomain",description:"احذف التشكيل والتطويل، ووحّد الألف والياء والهمزة، وحوّل الأرقام العربية-الهندية، واكشف المحارف غير المرئية التي تفسد مجموعات البيانات العربية. يعمل داخل متصفحك.",eyebrow:"للمطوّرين مع الذكاء الاصطناعي",heading:"هيّئ العربية ",headingAccent:"للفهرسة والتدريب",lede:"هيّئ النص العربي لفهرس بحث أو لمجموعة تدريب: احذف ما لا يحمل معنى، ووحّد الإملاءات التي سيتعلّمها النموذج مرّتين بلا داعٍ، واكشف المحارف غير المرئية التي تفسد مجموعة البيانات دون أن تظهر على الشاشة أبداً.",cta:{to:"/arabic-text",label:"افتح الأداة"},sections:[{title:"لماذا يهمّ توحيد الألف",body:["أ و إ و آ و ا حرف واحد في عين القارئ، وأربعة توكنات مختلفة في عين النموذج. المدوّنة التي تحتفظ بالأربعة تعلّم النموذج أن ينفق طاقته على تباين الإملاء بدل اللغة نفسها.","والأمر أوضح في البحث: فهرس يحتفظ بالأربعة يفشل في مطابقة الكلمة نفسها حين تُكتب من لوحة مفاتيح أخرى أو على عجل، وهو أشيع سبب لنتائج بحث عربية فارغة رغم وجود المحتوى."]},{title:"التشكيل ليس ضجيجاً دائماً",body:["حذف التشكيل يخفض عدد التوكنات بوضوح، وهو الصواب في النثر العادي. لكنه خطأ في النص القرآني والشعر والمواد التعليمية، حيث تحمل العلامات معنى ونطقاً. ولهذا هو مفتاح تختاره لا سلوك افتراضي."]},{title:"المحارف التي لا يراها أحد",body:["علامات الاتجاه ومحارف الوصل صفرية العرض تنجو من النسخ واللصق من ملف PDF أو تطبيق محادثة، ثم تستقرّ داخل ملف JSONL حيث لن يلحظها أي مراجع. تغيّر عدد التوكنات، وتكسر المقارنات التامّة، وتُبلَّغ هنا بالاسم والعدد."]}],faq:[{question:"لماذا أطبّع النص العربي قبل الفهرسة أو التدريب؟",answer:"أ و إ و آ و ا حرف واحد لدى القارئ وأربعة توكنات منفصلة لدى النموذج. المدوّنة التي تحتفظ بالأربعة تنفق طاقتها على تباين الإملاء بدل اللغة، وفهرس البحث الذي يحتفظ بها يفشل في مطابقة الكلمة نفسها حين تُكتب بصورة أخرى."},{question:"هل أحذف التشكيل دائماً؟",answer:"لا. حذف التشكيل يخفض عدد التوكنات كثيراً وهو الصواب في النثر العادي، لكنه خطأ في النص القرآني والشعر والمواد التعليمية حيث تحمل العلامات معنى ونطقاً. ولهذا هو مفتاح اختياري لا سلوك افتراضي."},{question:"ما هي المحارف غير المرئية في مجموعة بياناتي؟",answer:"علامات الاتجاه، ومحارف الوصل وعدم الوصل صفرية العرض، وما شابهها من محارف التنسيق. تنجو من النسخ واللصق من ملفات PDF وتطبيقات المحادثة ثم تستقرّ داخل ملفات JSONL دون أن يلحظها أحد، فتغيّر عدد التوكنات وتكسر المقارنات التامّة. تكشفها هذه الصفحة بالاسم والعدد."},{question:"هل تتعامل الأداة مع الأرقام العربية-الهندية؟",answer:"نعم. يمكن تحويل ١٢٣ وما شابهها إلى 123 حتى تتّسق المقارنة والترتيب مع بقية بياناتك."}],related:[{to:"/ar/tools",label:"كل أدوات المطوّرين"},{to:"/ar/token-calculator",label:"حاسبة التوكنات والتكلفة"},{to:"/ar/mock-data",label:"مولّد بيانات وهمية عربية"}]},"json-toolkit":{crumb:"أدوات JSON",features:["تنسيق وتصغير وتحقّق مع موضع الخطأ","ترتيب المفاتيح","مقارنة مستندين بالمسار لا بالأسطر","التحويل إلى واجهات TypeScript أو CSV أو YAML","يعمل داخل المتصفح ولا تُرفع الحمولة"],name:"أدوات JSON من FrugalDomain",title:"أدوات JSON — تنسيق وتحقّق ومقارنة وتحويل | FrugalDomain",description:"نسّق JSON وتحقّق من صحّته، ورتّب مفاتيحه، وقارن مستندين بالمسار، وحوّله إلى واجهات TypeScript أو CSV أو YAML. يعمل داخل المتصفح ولا يُرفع شيء.",eyebrow:"البيانات والصيغ",heading:"اقرأ ملف JSON ",headingAccent:"وافهم لماذا يرفض",lede:"اقرأ الحمولة، واعرف لماذا لا تُحلَّل، وقارنها بأخرى، وخذها إلى TypeScript أو CSV أو YAML. المستند يبقى في هذا التبويب — وهذا مهم، لأن ملف JSON الذي تصحّحه عادةً استجابة حقيقية ببيانات حقيقية.",cta:{to:"/json-toolkit",label:"افتح الأداة"},sections:[{title:"لماذا المقارنة بالمسار لا بالأسطر",body:["مقارنة الأسطر على JSON منسَّق تعدّ مفتاحاً أُعيد ترتيبه تغييرين، وكتلة أُعيدت إزاحتها مئة تغيير. المقارنة بالمسار تبلّغ عمّا اختلف فعلاً — سطر واحد لكل قيمة تغيّرت، ومعه المسار الذي كنت ستستخدمه للوصول إليها في الشيفرة."]},{title:"عن مخرجات TypeScript",body:["الكائنات داخل المصفوفة الواحدة تُدمج بدل إخراج واجهة لكل شكل: المفتاح الغائب عن بعض الصفوف يصبح اختيارياً، والمفتاح متغيّر النوع يصبح اتحاداً. هذا وصف لما ترجعه الواجهة فعلاً، بينما User1 و User2 و User3 كانت ستخفي هذا التباين لا أكثر."]},{title:"ما لا تستطيع CSV حمله",body:["الكائنات المتشعّبة تُسطَّح إلى أعمدة منقوطة، والمصفوفة المتشعّبة تصبح خلية واحدة تحمل JSON — فجدول البيانات لا مكان آخر لديه لوضعها، وتفكيكها كان سيغيّر عدد الصفوف بصمت."]}],faq:[{question:"لماذا لا يُحلَّل ملف JSON عندي؟",answer:"غالباً فاصلة زائدة في النهاية، أو علامة اقتباس مفردة مكان مزدوجة، أو اقتباس غير مهروب داخل نص، أو سطر جديد في وسط نص. الصق المستند وسيُبلَّغ الخطأ مع موضعه، وهو أسرع من قراءته بنفسك."},{question:"لماذا أقارن JSON بالمسار بدل الأسطر؟",answer:"لأن مقارنة الأسطر على JSON منسَّق تعدّ مفتاحاً أُعيد ترتيبه تغييرين وكتلة أُعيدت إزاحتها مئة تغيير. المقارنة بالمسار تبلّغ عمّا اختلف فعلاً: سطر واحد لكل قيمة، ومعه مسار الوصول إليها في الشيفرة."},{question:"كيف تُولَّد واجهات TypeScript؟",answer:"تُدمج الكائنات داخل المصفوفة الواحدة بدل إخراج واجهة لكل شكل: المفتاح الغائب عن بعض الصفوف يصبح اختيارياً، والمفتاح متغيّر النوع يصبح اتحاداً. هذا وصف لما ترجعه الواجهة فعلاً بدل إخفاء التباين خلف أسماء متعدّدة."},{question:"هل يمكن تحويل JSON المتشعّب إلى CSV؟",answer:"نعم، مع تحفّظ يستحق المعرفة. الكائنات المتشعّبة تُسطَّح إلى أعمدة منقوطة، والمصفوفة المتشعّبة تصبح خلية واحدة تحمل JSON — فجدول البيانات لا مكان لديه لوضعها، وتفكيكها كان سيغيّر عدد الصفوف بصمت."}],related:[{to:"/ar/tools",label:"كل أدوات المطوّرين"},{to:"/ar/mock-data",label:"مولّد بيانات وهمية عربية"},{to:"/ar/jsonl-validator",label:"مدقّق JSONL للتدريب"}]},"mock-data":{crumb:"بيانات وهمية عربية",features:["أسماء وعناوين وأرقام هواتف وشركات عربية","ملفات دول لسوريا والسعودية والإمارات ومصر والمغرب","مخرجات ببذرة — البذرة نفسها تعطي الصفوف نفسها","التصدير إلى JSON أو NDJSON أو CSV أو SQL أو TypeScript","يعمل داخل المتصفح"],name:"مولّد البيانات الوهمية العربية من FrugalDomain",title:"مولّد بيانات وهمية عربية — JSON وCSV وSQL | FrugalDomain",description:"ولّد أسماءً وعناوين وأرقام هواتف وشركات عربية واقعية لسوريا والسعودية والإمارات ومصر والمغرب. البذرة نفسها تعطي الصفوف نفسها. JSON أو NDJSON أو CSV أو SQL أو TypeScript.",eyebrow:"البيانات والصيغ",heading:"صفوف تشبه ",headingAccent:"مستخدميك فعلاً",lede:"املأ قاعدة بيانات أو ملف تجهيز بصفوف تشبه مستخدميك الحقيقيين: أسماء عربية، وأسماء مدن حقيقية، وأرقام هواتف بالشكل الذي تكتبه كل دولة. البذرة نفسها تنتج الصفوف نفسها دائماً، فيبقى ملف التجهيز ثابتاً وتبقى لقطة الشاشة قابلة للتكرار.",cta:{to:"/mock-data",label:"افتح المولّد"},sections:[{title:"لماذا ببذرة لا عشوائياً",body:["المولّد الذي يتغيّر في كل تشغيل لا يصلح لملف تجهيز، ولا لاختبار، ولا للقطة شاشة يجب أن تبدو كما هي غداً. البذرة هنا نص عادي: ضعها في الاختبار وستعود الصفوف نفسها بالضبط."]},{title:"لماذا تتّسق الصفوف مع بعضها",body:["البريد الإلكتروني مبنيّ من الاسم الذي فوقه، والمدينة من الدولة التي اخترتها. البيانات التي لا علاقة فيها للبريد بالاسم تبدو مزيّفة من النظرة الأولى، وهذا يبطل الغرض من الاختبار عليها أصلاً."]},{title:"ما ليست هذه الأداة",body:["ليست أداة خصوصية. الصفوف هنا مخترعة، ما يعني أنها آمنة للإيداع في المستودع — لكن استبدال بيانات عملاء حقيقيين ببيانات وهمية في تصدير مهمّة أخرى مختلفة تماماً، تحتاج حفظ الربط في مكان ما لا تراه هذه الصفحة أبداً."]}],faq:[{question:"لماذا البيانات مولَّدة ببذرة لا عشوائياً؟",answer:"لأن المولّد الذي يتغيّر في كل تشغيل لا يصلح لملف تجهيز ولا لاختبار ولا للقطة شاشة يجب أن تبقى كما هي. البذرة نص عادي: ضعها في الاختبار وتعود الصفوف نفسها في كل مرّة."},{question:"لماذا تتّسق الصفوف المولَّدة مع بعضها؟",answer:"لأن البريد الإلكتروني مبنيّ من الاسم الذي فوقه والمدينة من الدولة التي اخترتها. الصفوف التي لا علاقة فيها للبريد بالاسم تبدو مزيّفة من النظرة الأولى، وهذا يبطل الغرض من اختبار الواجهة عليها."},{question:"هل أستطيع استخدامها لإخفاء هوية بيانات عملاء حقيقيين؟",answer:"لا. الصفوف هنا مخترعة وآمنة للإيداع في المستودع، لكن استبدال قيم حقيقية بأخرى وهمية في تصدير مهمّة مختلفة تحتاج حفظ الربط في مكان ما، وهذه الصفحة لا ترى بياناتك أصلاً."},{question:"ما الصيغ التي يمكن تصديرها؟",answer:"JSON و NDJSON و CSV وجمل إدراج SQL ومصفوفة TypeScript، فتذهب الصفوف مباشرةً إلى سكربت تهيئة أو ملف تجهيز أو جدول بيانات دون إعادة تشكيل."}],related:[{to:"/ar/tools",label:"كل أدوات المطوّرين"},{to:"/ar/json-toolkit",label:"أدوات JSON"},{to:"/ar/arabic-text",label:"أدوات النص العربي"}]},"svg-toolkit":{crumb:"أدوات SVG",features:["التحسين: إزالة بيانات المحرّر وتقريب الأرقام وإضافة viewBox الناقص","التحويل إلى React JSX وVue","التحويل إلى React Native وFlutter","التحويل إلى VectorDrawable للأندرويد","الإخراج بصيغة data URI أو خلفية CSS"],name:"أدوات SVG من FrugalDomain",title:"أدوات SVG — تحسين وتحويل إلى JSX وVue وFlutter وAndroid | FrugalDomain",description:"نظّف ملف SVG وحوّله إلى React أو Vue أو React Native أو Flutter أو VectorDrawable للأندرويد أو data URI أو CSS. يعمل كلياً داخل متصفحك ولا يُرفع شيء.",eyebrow:"للواجهة الأمامية",heading:"نظّف ملف SVG ",headingAccent:"ثم حوّله",lede:"انزع بقايا المحرّر من ملف SVG، وقرّب أرقامه، ثم خذه مكوّناً في React أو Vue أو React Native أو Flutter أو أندرويد. كل ذلك يحدث في هذا التبويب — الملف لا يُرفع إلى أي مكان.",cta:{to:"/svg-toolkit",label:"افتح الأداة"},sections:[{title:"ما الذي يزيله المحسّن",body:["التعليقات، وكتل البيانات الوصفية، والسمات ذات النطاقات التي تتركها برامج الرسم خلفها، والمجموعات الفارغة. وتُقرَّب الأرقام إلى الدقّة التي تختارها، ويُضاف viewBox حين يكون الملف خالياً منه."]},{title:"ما يمتنع عنه عمداً",body:["لن يدمج المسارات، ولن يسطّح التحويلات، ولن يحذف معرّفاً يشير إليه شيء آخر. هذه توفّر بايتات لكنها قد تغيّر شكل الملف أو تكسر مرجعاً قائماً، وأيقونة أصغر تُعرض بشكل مختلف ليست مكسباً."]},{title:"عن مخرجات أندرويد",body:["لا يرسم VectorDrawable إلا المسارات، لذا تُحوَّل المستطيلات والدوائر والمضلّعات إلى مسارات أولاً. أمّا التدرّجات والمرشّحات والنصوص فلا مقابل لها، ولهذا يُبلَّغ عنها لك بدل حذفها بصمت."]}],faq:[{question:"كيف أحوّل ملف SVG إلى مكوّن React؟",answer:"الصق الملف واختر مخرجات React. تُعاد تسمية السمات إلى صيغها في JSX، ويُغلَّف الترميز في مكوّن، وتُمرَّر الخصائص حتى يمكن ضبط الحجم واللون من موضع الاستدعاء. ولا يُرفع شيء — التحويل يجري داخل التبويب."},{question:"ما الذي يزيله المحسّن فعلاً؟",answer:"التعليقات، وكتل البيانات الوصفية، والسمات ذات النطاقات التي تتركها برامج الرسم، والمجموعات الفارغة. وتُقرَّب الأرقام إلى الدقّة التي تختارها، ويُضاف viewBox حين يكون الملف خالياً منه."},{question:"لماذا لا يدمج المسارات أو يسطّح التحويلات؟",answer:"لأن هذه العمليات توفّر بايتات لكنها قد تغيّر شكل الملف أو تكسر معرّفاً يشير إليه شيء آخر. أيقونة أصغر تُعرض بشكل مختلف ليست مكسباً، لذا يتوقّف المحسّن قبل كل ما يخاطر بذلك."},{question:"هل يحوّل SVG إلى VectorDrawable للأندرويد؟",answer:"نعم. وبما أن VectorDrawable لا يرسم إلا المسارات، تُحوَّل المستطيلات والدوائر والمضلّعات إلى مسارات أولاً. والتدرّجات والمرشّحات والنصوص لا مقابل لها، فيُبلَّغ عنها بدل حذفها بصمت."}],related:[{to:"/ar/IconsGalary",label:"مكتبة أيقونات SVG مجانية"},{to:"/ar/favicon-generator",label:"مولّد الأيقونات المفضّلة"},{to:"/ar/vector-editor",label:"محرر الرسوم المتجهة"}]},"favicon-generator":{crumb:"مولّد الأيقونات المفضّلة",features:["ملف favicon.ico يحمل صور 16 و32 و48 بكسل","أيقونات PNG للتبويب","أيقونة apple-touch-icon معتمة لنظام iOS","أيقونة أندرويد تكيّفية قابلة للقصّ","ملف بيان تطبيق الويب ومقتطف HTML للّصق"],name:"مولّد الأيقونات المفضّلة وأيقونات التطبيقات من FrugalDomain",title:"مولّد الأيقونة المفضّلة وأيقونات التطبيقات — كل المقاسات | FrugalDomain",description:"حوّل شعاراً واحداً إلى favicon.ico وأيقونات التبويب وأيقونة iOS وأيقونات أندرويد والأيقونة القابلة للقصّ، مع ملف البيان ومقتطف HTML. لا يُرفع شيء.",eyebrow:"للواجهة الأمامية",heading:"شعار واحد، ",headingAccent:"كل المقاسات",lede:"رسم واحد، وكل مقاس يطلبه متصفح أو هاتف — بما فيها أيقونة iOS المعتمة والأيقونة القابلة للقصّ في أندرويد، وهما الاثنتان اللتان تُشحنان معطوبتين عادةً. الشعار يُرسم في هذا التبويب ولا يُرفع أبداً.",cta:{to:"/favicon-generator",label:"افتح المولّد"},sections:[{title:"لماذا تُملأ أيقونة iOS بخلفية",body:["يركّب Safari أيقونة الشاشة الرئيسية الشفافة فوق خلفية سوداء، فيختفي الشعار المرسوم بحبر داكن تماماً. لذا يُمنح ملف apple-touch-icon.png خلفيةً دائماً هنا، مهما كانت بقية المقاسات."]},{title:"ما معنى «قابلة للقصّ»",body:["يقصّ أندرويد الأيقونة التكيّفية إلى الشكل الذي يستخدمه المشغّل — دائرة أو مربّع دائري أو مربّع بحواف — وقد يقتطع نحو عشرين بالمئة من كل حافة. ولهذا يُبقي الملف القابل للقصّ الرسم داخل المنطقة الآمنة بهامش مريح."]},{title:"عن ملف favicon.ico",body:["يحمل ملف .ico هنا صور 16 و32 و48 بكسل بصيغة PNG داخل الحاوية، وهو ما يقرأه كل متصفح منذ Vista. وما زال يستحق الشحن: الإشارات المرجعية والمتصفحات الأقدم وبعض قارئات الخلاصات تطلب ‎/favicon.ico‎ بالاسم وتتجاهل وسوم الربط تماماً."]}],faq:[{question:"ما مقاسات الأيقونة المفضّلة التي أحتاجها فعلاً؟",answer:"ملف favicon.ico يحمل صور 16 و32 و48 بكسل، وأيقونات PNG للتبويب، وأيقونة 180 بكسل لنظام iOS، وأيقونات أندرويد مع نسخة قابلة للقصّ. تنتج هذه الصفحة كل ذلك من رسم واحد، مع ملف البيان ووسوم الربط الجاهزة للّصق."},{question:"لماذا تُعطى أيقونة iOS خلفية؟",answer:"لأن Safari يركّب الأيقونة الشفافة فوق خلفية سوداء، فيختفي الشعار المرسوم بحبر داكن. لذا يُولَّد ملف apple-touch-icon.png بخلفية دائماً هنا، مهما كانت بقية المقاسات."},{question:"ما معنى الأيقونة القابلة للقصّ في أندرويد؟",answer:"يقصّ أندرويد الأيقونة التكيّفية إلى شكل المشغّل — دائرة أو مربّع دائري أو مربّع بحواف — وقد يقتطع نحو عشرين بالمئة من كل حافة. والملف القابل للقصّ يبقي الرسم داخل المنطقة الآمنة فينجو مع أي مشغّل."},{question:"هل ما زلت أحتاج ملف favicon.ico؟",answer:"نعم، ما زال يستحق الشحن. الإشارات المرجعية والمتصفحات الأقدم وبعض قارئات الخلاصات تطلب ‎/favicon.ico‎ بالاسم وتتجاهل وسوم الربط. والملف المنتَج هنا يحمل صور 16 و32 و48 بكسل بصيغة PNG داخل الحاوية، وهو ما يقرأه كل متصفح منذ Vista."}],related:[{to:"/ar/svg-toolkit",label:"أدوات SVG"},{to:"/ar/IconsGalary",label:"مكتبة أيقونات SVG مجانية"},{to:"/ar/ImageConvert",label:"تحويل الصور"}]},"jwt-decoder":{crumb:"فاكّ ترميز JWT",name:"فاكّ ترميز JWT والتحقق من التوقيع",title:"فاكّ ترميز JWT والتحقق من توقيعه داخل المتصفح | FrugalDomain",description:"افكّ ترميز رمز JWT واقرأ مطالباته بأوقات مفهومة، وتحقّق من توقيع HS256 أو RS256 بمفتاحك أنت — كل ذلك داخل المتصفح دون أن يغادر الرمز تبويبك.",eyebrow:"أدوات المطوّرين",heading:"اقرأ رمز JWT ",headingAccent:"وتحقّق من توقيعه",lede:"معظم أدوات فكّ الترميز تتوقف عند base64، والنصف المهم — هل التوقيع صحيح — هو النصف الذي يدفع الناس للصق رموز إنتاجية في خادم غريب. هنا يجري التحقق داخل تبويبك عبر WebCrypto، فلا يغادر الرمز ولا المفتاح جهازك.",cta:{to:"/jwt-decoder",label:"افتح الأداة"},sections:[{title:"لماذا لا تلصق رمزاً حقيقياً في أي موقع؟",body:["رمز JWT هو بطاقة حامل: من يملكه يستطيع التصرّف نيابة عن صاحبه حتى انتهاء صلاحيته. لصق رمز حيّ في خادم لا تملكه يساوي تسليم حساب، لا فحص بيانات.","هذه الصفحة تفكّ الترميز وتتحقّق من التوقيع كلياً داخل المتصفح. يمكنك فتحها ثم قطع الاتصال بالشبكة وستستمر في العمل — وهذا أبسط اختبار لصدق أي أداة تقول إنها لا ترفع شيئاً."]},{title:"فكّ الترميز شيء والتحقق شيء آخر",body:["أي شخص يستطيع قراءة محتوى JWT لأن الحمولة مرمّزة بـbase64 لا مشفّرة. ما يثبت أن الرمز صادر من خادمك هو التوقيع، والتحقق منه يحتاج المفتاح: السرّ المشترك في HS256، أو النصف العام من المفتاح في RS256 — وهو النصف الآمن للّصق.","الأداة تنبّه أيضاً على رمز يقول ترويسته alg: none، أي بلا توقيع أصلاً. المكتبات التي تحترم هذه الترويسة تقبل رمزاً كتبه أي شخص، وهي أقدم ثغرة في JWT ولا تزال تُصادَف."]},{title:"أوقات مقروءة بدل أرقام حقبة",body:["المطالبات الزمنية مثل exp وnbf وiat تُعرض بتوقيتك المحلي مع وصف نسبي (منذ سنة، بعد ساعتين) بدل ثوانٍ منذ 1970، لأن الخطأ المعتاد في هذه الرموز هو صلاحية منتهية أو لم تبدأ بعد."]}],faq:[{question:"هل من الآمن لصق رمز JWT في موقع على الإنترنت؟",answer:"غالباً لا. الرمز بطاقة حامل يستطيع من يملكها انتحال صاحبها حتى انتهاء صلاحيتها. استخدم أداة تعمل داخل المتصفح مثل هذه، أو افكّ الترميز محلياً بمكتبة في مشروعك."},{question:"كيف أتحقّق من توقيع JWT بلا خادم؟",answer:"عبر WebCrypto المدمج في المتصفح. ألصق السرّ المشترك لرموز HS256، أو المفتاح العام بصيغة PEM لرموز RS256، ويجري الفحص محلياً. لا تلصق مفتاحاً خاصاً أو سرّ إنتاج في أي صفحة لا تملكها."},{question:"ماذا تعني alg: none؟",answer:"تعني أن الرمز بلا توقيع. المكتبة التي تقبل هذه الترويسة تقبل رمزاً كتبه أي شخص. ارفضها على مستوى المكتبة وثبّت قائمة الخوارزميات المقبولة عندك."},{question:"لماذا لا تدعم الأداة رموز ES256؟",answer:"رموز المنحنيات الإهليلجية تحتاج زوج التوقيع الخام ومساراً مختلفاً لاستيراد المفتاح، وتنفيذ نصف صحيح أسوأ من لا شيء. الصفحة تقول ذلك صراحة بدل أن تدّعي."}],related:[{to:"/ar/json-toolkit",label:"أدوات JSON"},{to:"/ar/token-calculator",label:"حاسبة التوكنات والتكلفة"},{to:"/ar/tools",label:"كل أدوات المطوّرين"}]},"cron-builder":{crumb:"باني تعبير cron",name:"باني تعبير cron وشارحه",title:"باني تعبير cron مع أوقات التشغيل القادمة | FrugalDomain",description:"اكتب تعبير cron أو الصقه، اقرأه كجملة مفهومة، وشاهد المواعيد الثمانية القادمة التي سيعمل فيها فعلاً بتوقيتك أو بتوقيت UTC.",eyebrow:"أدوات المطوّرين",heading:"اكتب الجدولة ",headingAccent:"وشاهد متى تعمل",lede:"شرح التعبير بجملة موجود في كل أداة، لكن المواعيد القادمة هي ما يكشف الخطأ. تعبيران قد يُقرآن بصيغة متشابهة ويعملان في أيام مختلفة تماماً، وقائمة التواريخ تحسم الأمر بنظرة واحدة.",cta:{to:"/cron-builder",label:"افتح الأداة"},sections:[{title:"الفخّ الأشهر: يوم الشهر ويوم الأسبوع",body:["حين يكون الحقلان مقيّدين معاً، يعمل cron إذا تطابق أحدهما لا كلاهما. لذلك فإن 0 0 1 * 1 يعمل في أول الشهر وفي كل يوم اثنين — وهو تقريباً ليس ما قصده من كتبه.","الأداة تذكر هذه القاعدة صراحة عند تقييد الحقلين، وتعرض التواريخ القادمة التي تجعل الأثر مرئياً فوراً."]},{title:"بتوقيت من تعمل الجدولة؟",body:["خدمة cron على الخادم تعمل بالتوقيت المحلي للجهاز، بينما تعتمد معظم المجدولات السحابية توقيت UTC افتراضياً. الفارق ينقل مهمة ليلية عدة ساعات، وينقلها مرة أخرى عند بدء التوقيت الصيفي، ولهذا تعرض الصفحة التوقيتين."]},{title:"خمسة حقول لا ستة",body:["إضافة حقل للثواني وصيغ مثل L وW و# هي امتدادات Quartz وSpring لا cron القياسي. الأداة ترفضها بدل أن تتجاهل الحقل الزائد، لأن جدولة تُسقط حقلاً بصمت هي جدولة تعمل في الوقت الخطأ."]}],faq:[{question:"ماذا يعني التعبير 0 0 * * 0؟",answer:"منتصف ليل كل يوم أحد. الحقول بالترتيب: الدقيقة، الساعة، يوم الشهر، الشهر، يوم الأسبوع. الصقه في الأداة وستؤكّده التواريخ الثمانية القادمة."},{question:"لماذا تعمل مهمة cron في أيام غير متوقعة؟",answer:"غالباً بسبب قاعدة يوم الشهر ويوم الأسبوع: عند تقييد الحقلين يعمل cron إذا تطابق أحدهما لا كلاهما. اعرض المواعيد القادمة وسترى ذلك مباشرة."},{question:"هل يستخدم cron توقيت UTC أم التوقيت المحلي؟",answer:"خدمة cron تستخدم توقيت الجهاز المحلي، ومعظم المجدولات السحابية تستخدم UTC. راجع العمودين في الصفحة قبل اعتماد أي جدولة ليلية."},{question:"لماذا رُفض تعبيري المكوّن من ستة حقول؟",answer:"لأن الحقل السادس حقل ثوانٍ تقبله Quartz وSpring ولا يقبله cron القياسي. احذفه، أو استخدم صيغة المجدول الذي تعمل عليه."}],related:[{to:"/ar/json-toolkit",label:"أدوات JSON"},{to:"/ar/jwt-decoder",label:"فاكّ ترميز JWT"},{to:"/ar/tools",label:"كل أدوات المطوّرين"}]},"text-diff":{crumb:"مقارنة النصوص",name:"مقارنة النصوص وملفات JSON",title:"مقارنة نصّين أو ملفَّي JSON داخل المتصفح | FrugalDomain",description:"قارن نصّين سطراً بسطر مع تحديد الكلمات المتغيّرة داخل كل سطر، وصدّر النتيجة بصيغة unified diff. لا يُرفع شيء إلى أي خادم.",eyebrow:"أدوات المطوّرين",heading:"قارن نسختين ",headingAccent:"وشاهد الكلمة المتغيّرة",lede:"مقارنة الأسطر متاحة في كل مكان، لكن ما يجعلها مقروءة هو تحديد الكلمات المتغيّرة داخل السطر، ورفض مزاوجة سطرين لا علاقة بينهما. الاثنان هنا، وكل شيء يجري داخل التبويب.",cta:{to:"/text-diff",label:"افتح الأداة"},sections:[{title:"لماذا تهمّ المقارنة على مستوى الكلمة؟",body:["مقارنة الأسطر تقول إن السطر تغيّر؛ مقارنة الكلمات تقول أي كلمة تغيّرت. في ملف إعدادات أو ترجمة أو عقد، هذا هو الجواب كله — ولهذا يُعرض السطر المتغيّر مرتين: مرة بما خرج ومرة بما دخل."]},{title:"ما تقارنه غالباً لا يصحّ رفعه",body:["الناس يقارنون ملفات إعدادات واستجابات واجهات برمجية وعقوداً وترجمات. هذه ليست نصوصاً محايدة تُلصق في خادم غريب لاكتشاف كلمة تغيّرت، ولذلك تجري المقارنة كاملة في المتصفح."]},{title:"وللـJSON: قارن بالمسار",body:["مقارنة نصية لملف JSON تعتبر إعادة ترتيب مفتاح تغييراً، وإعادة الإزاحة مئة تغيير. إن كان ما تقارنه حمولة واجهة برمجية فالأفضل مقارنتها بالمسار — وهو ما تفعله أداة JSON في هذا الموقع."]}],faq:[{question:"كيف أقارن نصّين بأمان على الإنترنت؟",answer:"استخدم أداة تجري المقارنة داخل المتصفح. ما يُقارَن عادةً ملف إعدادات أو عقد أو ترجمة، ولا يصحّ إرساله إلى خادم لاكتشاف فرق كلمة واحدة."},{question:"ما هي صيغة unified diff؟",answer:"الصيغة التي يستخدمها git وpatch: أسطر سياق قليلة حول كل تغيير، مع علامة - للمحذوف و+ للمضاف. وهي الصيغة المناسبة للّصق في طلب دمج أو تذكرة، والأداة تصدّرها."},{question:"لماذا يظهر بعض التغيير كحذف وإضافة منفصلين؟",answer:"لأن السطرين ليسا إعادة كتابة لبعضهما. حين يتشارك السطر المحذوف والمضاف قدراً ضئيلاً من النص، تكون مزاوجتهما صفّاً تتلوّن فيه كل الكلمات تقريباً — وهو أقل وضوحاً من عرضهما منفصلين."},{question:"هل تصلح الأداة لمقارنة ملفات JSON؟",answer:"للملفات نعم. أما حمولات الواجهات البرمجية فالأفضل مقارنتها بالمسار عبر أداة JSON، لأن المقارنة النصية تضخّم فروق الترتيب والإزاحة."}],related:[{to:"/ar/json-toolkit",label:"أدوات JSON"},{to:"/ar/arabic-text",label:"حقيبة النص العربي"},{to:"/ar/tools",label:"كل أدوات المطوّرين"}]},"tool-schema":{crumb:"باني مخططات الأدوات",name:"باني مخططات الأدوات لاستدعاء الدوال",title:"باني مخطط أداة لاستدعاء الدوال — Anthropic وOpenAI وGemini وMCP | FrugalDomain",description:"صِف الأداة مرّة واحدة واحصل على تعريفها بالشكل الذي يقبله كل مزوّد، مع فحوص للأمور التي تجعل النموذج يستدعي الأداة الخطأ.",eyebrow:"أدوات المطوّرين",heading:"تعريف واحد ",headingAccent:"لكل المزوّدين",lede:"مخطط JSON للوسائط واحد عند الجميع، والمختلف هو الغلاف: input_schema عند Anthropic، وparameters عند OpenAI وGemini، وinputSchema في MCP. كتابته أربع مرات يدوياً هو سبب نجاح الأداة مع مزوّد وفشلها الصامت مع آخر.",cta:{to:"/tool-schema",label:"افتح الأداة"},sections:[{title:"الوصف هو التوجيه",body:["النموذج لا يرى شيفرتك، بل يرى اسم الأداة ووصفها ويقرّر منهما. «بحث في الطلبات» تخمين، أما «ابحث في طلبات العميل القائمة؛ لا تستخدمها لإنشاء طلب أو إلغائه» فتعليمة — والشقّ المنفي هو ما يمنع معظم الاستدعاءات الخاطئة."]},{title:"القوائم المغلقة أفضل من النص الحر",body:["وسيط حالة موصوف كنصّ يدعو النموذج لاختراع قيمة. الوسيط نفسه بأربع قيم مسموحة لا يمكن ملؤه خطأً، ولا يحتاج تحققاً إضافياً عندك بعد المخطط.","الأداة تنبّه أيضاً على الكائنات الحرّة بلا حقول، لأن النماذج تملؤها بشكل رديء مقارنة بحقول محدّدة الأسماء."]},{title:"وMCP أيضاً",body:["خوادم Model Context Protocol تُعيد أدواتها من tools/list بكائنات فيها الاسم والوصف وinputSchema — المخطط نفسه بغلاف إضافي. الأداة تُخرجه إلى جانب صيغ المزوّدين."]}],faq:[{question:"ما الفرق بين تعريف الأداة عند Anthropic وOpenAI وGemini؟",answer:"مخطط JSON للوسائط متطابق، والغلاف هو المختلف: input_schema عند Anthropic، وparameters عند OpenAI، وfunctionDeclarations عند Gemini، وinputSchema في MCP."},{question:"لماذا يستدعي النموذج الأداة الخطأ؟",answer:"غالباً بسبب الوصف. النموذج يختار الأداة من اسمها ووصفها، فالوصف المبهم يجعل الاختيار أقرب إلى الحظ. اذكر ما تفعله الأداة، ومتى تُستخدم، ومتى لا تُستخدم."},{question:"هل أستخدم enum في وسائط الأداة؟",answer:"نعم كلما كانت القيم محدودة. القائمة المغلقة تمنع القيم المخترعة وتغنيك عن تحقق إضافي في شيفرتك."},{question:"هل يمكن تصدير التعريف لخادم MCP؟",answer:"نعم، الأداة تُخرج صيغة MCP كما تُعيدها tools/list، إلى جانب صيغ Anthropic وOpenAI وGemini ومخطط JSON الخام."}],related:[{to:"/ar/agents-md",label:"مولّد AGENTS.md"},{to:"/ar/token-calculator",label:"حاسبة التوكنات والتكلفة"},{to:"/ar/tools",label:"كل أدوات المطوّرين"}]},"prompt-library":{crumb:"مكتبة البرومبتات",name:"مكتبة البرومبتات",title:"مكتبة برومبتات بمتغيّرات ونسخ داخل متصفحك | FrugalDomain",description:"احفظ برومبتاتك في مكان واحد، وحوّل متغيّراتها إلى حقول تملؤها، وانسخ الناتج، واسترجع نسخة سابقة حين يفسد تعديل ما. كل شيء داخل متصفحك.",eyebrow:"أدوات المطوّرين",heading:"برومبتاتك في ",headingAccent:"مكان واحد",lede:"البرومبتات التي يعتمد عليها فريق تنتهي في سجلّ محادثة وتطبيق ملاحظات وثلاث حافظات — ولهذا يوجد من البرومبت نفسه أربع نسخ لا أحد يعرف أيها الجيدة. هنا لها بيت واحد، ومتغيّراتها حقول، ونسختها السابقة محفوظة.",cta:{to:"/prompt-library",label:"افتح الأداة"},sections:[{title:"لماذا التخزين في المتصفح؟",body:["البرومبت غالباً أكثر ما يملكه الفريق خصوصية: فيه طريقة مخاطبة العملاء وشكل البيانات وحدود المسموح. تخزينه في متصفحك يعني ألا حساب يُخترق ولا نسخة منه على قرص أحد آخر.","الثمن أنه يبقى في هذا المتصفح، ولهذا التصدير والاستيراد ليسا إضافة جانبية: ملف JSON هو وسيلة المزامنة والمشاركة مع الفريق."]},{title:"متغيّرات بدل نسخ متشابهة",body:["عشرة برومبتات متطابقة تقريباً بكلمة مختلفة هي بداية فوضى المكتبة. برومبت واحد بمتغيّرات يبقى شيئاً واحداً تحسّنه، والحقول تجعل الفروق ظاهرة بدل أن تختفي وسط فقرة."]},{title:"النسخ تنقذ التعديل السيئ",body:["كلما تغيّر النص حُفظت النسخة السابقة، حتى عشر نسخ. تعديلات البرومبتات صعبة التقييم وسهلة الندم، واسترجاع بنقرة واحدة هو الفرق بين التجريب والتخمين."]}],faq:[{question:"أين تُحفظ برومبتاتي؟",answer:"في تخزين المتصفح المحلي على جهازك. لا حساب ولا نسخة على خادم — ولهذا لا تنتقل معك إلى متصفح آخر إلا بتصدير ملف JSON واستيراده هناك."},{question:"كيف تعمل المتغيّرات؟",answer:"اكتب المتغيّر بين قوسين معقوفين مزدوجين في أي موضع من البرومبت فيصبح حقلاً. ملء الحقل يستبدل القيمة، وما يبقى فارغاً يظل ظاهراً كعنصر نائب لتعرف ما ينقصك."},{question:"لماذا أحتفظ بنسخ من البرومبت؟",answer:"لأن تعديلاً صغيراً قد يفسد المخرجات بطريقة لا تُكتشف فوراً. النسخة السابقة محفوظة ويمكن استرجاعها بنقرة."},{question:"هل يمكن مشاركة المكتبة مع الفريق؟",answer:"نعم، صدّرها ملف JSON وشاركه كما تشارك أي ملف. الاستيراد يدمج حسب العنوان فلا يكرّر ما سبق استيراده."}],related:[{to:"/ar/token-calculator",label:"حاسبة التوكنات والتكلفة"},{to:"/ar/agents-md",label:"مولّد AGENTS.md"},{to:"/ar/tools",label:"كل أدوات المطوّرين"}]},"og-image":{crumb:"مولّد صور المشاركة",name:"مولّد صور Open Graph",title:"مولّد صور Open Graph لبطاقات المشاركة مع وسوم الميتا | FrugalDomain",description:"حوّل عنواناً ووصفاً إلى بطاقة مشاركة بمقاس 1200×630 مع وسوم الميتا المرافقة، مرسومة داخل متصفحك دون رفع أي شيء.",eyebrow:"أدوات المطوّرين",heading:"بطاقة مشاركة ",headingAccent:"من عنوانك",lede:"الصفحة التي بلا og:image تظهر ببطاقة فارغة في كل منصّة تُنشر فيها. الأداة ترسم البطاقة من العنوان الذي كتبته أصلاً، بالمقاس الذي تتوقعه كل منصّة، وتعطيك وسوم الميتا لتلصقها بجانبها.",cta:{to:"/og-image",label:"افتح الأداة"},sections:[{title:"لماذا 1200×630؟",body:["هو المقاس الذي تقصّه فيسبوك ولينكدإن وإكس بأقل قدر، ويبقى نصّه مقروءاً حين تُعرض البطاقة بثلث عرضها في التسلسل. المربّع أنسب لتطبيقات المحادثة التي تعرض مصغّرة صغيرة."]},{title:"الصورة يجب أن تكون قابلة للوصول",body:["زواحف المنصّات تجلب og:image عبر الإنترنت العام قبل أن تعرض شيئاً، فالمسار النسبي أو نطاق التجربة أو ملف خلف تسجيل دخول كلها تنتج بطاقة فارغة. استخدم رابط https كاملاً على الموقع الحيّ."]},{title:"والمنصّات تخزّن البطاقة مؤقتاً",body:["بعد أول جلب تستمر المنصّة في عرض البطاقة القديمة أياماً. مصحّح المشاركة في فيسبوك وأداة معاينة المنشور في لينكدإن يجبران على إعادة الجلب، وإكس يحدّثها وفق جدولته، ولهذا قد يكون تغيير اسم الملف أسرع."]}],faq:[{question:"ما المقاس المناسب لصورة Open Graph؟",answer:"‏1200×630 بكسل. هو المقاس الأقل تعرّضاً للقصّ في فيسبوك ولينكدإن وإكس، ويبقى مقروءاً عند العرض المصغّر في التسلسل."},{question:"لماذا لا تظهر صورة المشاركة لصفحتي؟",answer:"ثلاثة أسباب معتادة: الرابط نسبي لا مطلق، أو الملف خلف تسجيل دخول أو على نطاق تجريبي لا يصله الزاحف، أو المنصّة خزّنت بطاقة قديمة. أعد الجلب من أدوات المطوّرين في المنصّة نفسها."},{question:"هل أحتاج صورة منفصلة لإكس؟",answer:"لا. مع twitter:card بقيمة summary_large_image تستخدم إكس صورة Open Graph نفسها، والصورة المنفصلة تلزم فقط إن أردت صورة مختلفة هناك."},{question:"هل تؤثر صورة المشاركة في ترتيب البحث؟",answer:"ليست عامل ترتيب مباشراً، لكنها ترفع نسبة النقر على كل رابط يشير إلى صفحتك من المنصّات والمحادثات، وهو سبب كافٍ لعدم تركها فارغة."}],related:[{to:"/ar/favicon-generator",label:"مولّد الأيقونات والفافيكون"},{to:"/ar/svg-toolkit",label:"أدوات SVG"},{to:"/ar/tools",label:"كل أدوات المطوّرين"}]},"code-image":{crumb:"تحويل الكود إلى صورة",name:"تحويل الكود إلى صورة",title:"حوّل مقطع كود إلى صورة PNG جاهزة للمشاركة | FrugalDomain",description:"الصق مقطع كود واحصل على صورة بإطار نافذة وتلوين وأرقام أسطر، مرسومة داخل متصفحك بضعف الدقة ودون رفع المقطع إلى أي خادم.",eyebrow:"أدوات المطوّرين",heading:"الكود كصورة ",headingAccent:"حيث لا يُعرض كنصّ",lede:"الشرائح والمنشورات ورسائل العملاء تسطّح كتلة الكود إلى نصّ غير مقروء. الصورة تحفظ الإزاحة والألوان، وهي معظم ما يجعل الكود مفهوماً بنظرة — وهنا تُرسم داخل تبويبك لا على خادم أحد.",cta:{to:"/code-image",label:"افتح الأداة"},sections:[{title:"لماذا لا ترفع مقاطعك؟",body:["معظم الخدمات المشابهة ترسل المقطع إلى خادم ليُرسم هناك، وهذا إفشاء إن احتوى الكود مفاتيح أو بيانات عملاء أو عملاً غير منشور. الرسم هنا يتم على canvas في تبويبك."]},{title:"صورة للعرض لا للتوثيق",body:["الصورة لا تُنسخ ولا تُبحث ولا تُترجم ولا يقرؤها قارئ الشاشة. استخدمها لعرض الكود في شريحة أو منشور، وأرفق النصّ دائماً حين يحتاج القارئ إلى تشغيل المقطع."]},{title:"التلوين المختصر عن قصد",body:["المميّز هنا يلوّن النصوص والتعليقات والأرقام والكلمات المفتاحية — وهي الأربعة التي تحمل تقريباً كل المعلومة البصرية. قواعد لغة كاملة لكل لغة تعني ميغابايت من المحلّلات مقابل صورة، وهي مقايضة لا تستحق داخل تبويب متصفح."]}],faq:[{question:"كيف أحوّل كوداً إلى صورة؟",answer:"الصقه هنا، واختر اللغة والسمة، ثم نزّل ملف PNG. الصورة تُرسم في متصفحك بضعف دقة العرض لتبقى حادّة عند التكبير."},{question:"هل الأدوات المستضافة لتحويل الكود إلى صورة آمنة؟",answer:"فقط إن كان الرسم محلياً. أغلبها يرسل المقطع إلى خادم، وهو ما لا يصحّ مع كود فيه مفاتيح أو بيانات عملاء."},{question:"هل أستخدم صور الكود في التوثيق؟",answer:"لا. الصورة لا تُنسخ ولا تُبحث ولا يقرؤها قارئ الشاشة. اجعلها للعرض فقط وأرفق النصّ."},{question:"ما اللغات المدعومة في التلوين؟",answer:"جافاسكربت وJSON وHTML وCSS وPHP وبايثون وأوامر الطرفية، إضافة إلى النصّ العادي."}],related:[{to:"/ar/og-image",label:"مولّد صور المشاركة"},{to:"/ar/svg-toolkit",label:"أدوات SVG"},{to:"/ar/tools",label:"كل أدوات المطوّرين"}]},playground:{crumb:"ملعب الكمبوننت",name:"ملعب مكوّنات HTML",title:"ملعب HTML — عاين مكوّناً بملف واحد بأي عرض وسمة واتجاه | FrugalDomain",description:"عدّل مكوّن HTML مكتفياً بذاته وشاهده يُرسم فوراً بعرض الهاتف أو اللوحي أو سطح المكتب، في الوضع الفاتح والداكن ومن اليمين إلى اليسار.",eyebrow:"أدوات المطوّرين",heading:"عدّل المكوّن ",headingAccent:"وشاهده فوراً",lede:"كل قالب في مكتبة الكمبوننت ملف HTML واحد مكتفٍ بذاته، وهذا بالضبط ما يستطيع إطار مدمج أن يرسمه من نصّ. لا خطوة بناء ولا خادم ولا خدمة معاينة خارجية.",cta:{to:"/playground",label:"افتح الأداة"},sections:[{title:"لماذا ملف واحد؟",body:["المكوّن الذي هو ملف HTML واحد يمكن معاينته بإطار مدمج، وقراءته في جلسة واحدة، ولصقه في أي بنية — بلا خطوة بناء ولا شجرة اعتماديات ولا شيء يُجلب وقت التشغيل. هذه هي فكرة المكتبة التي تعدّلها هذه الصفحة."]},{title:"ما يسمح به الصندوق الرملي",body:["الإطار يشغّل السكربتات ليعمل سلوك المكوّن نفسه، ويُمنع من الوصول لنفس الأصل ومن النماذج والنوافذ المنبثقة والتنقّل. أي شيفرة تلصقها لا تستطيع قراءة هذه الصفحة ولا تخزينها ولا كوكيز متصفحك."]},{title:"اختبر الداكن والـRTL قبل النشر",body:["المبدّلان يعيدان كتابة سمات المستند نفسه بدل فرض أنماط من الخارج، فما تراه هو ما يفعله الملف وحده. التخطيط الذي ينعكس صحيحاً لأن الصفحة الأم ساعدته سينكسر في مكان آخر."]}],faq:[{question:"كيف أعاين ملف HTML بلا خادم؟",answer:"الصق الملف في الصفحة فيُرسم داخل إطار مدمج من النصّ نفسه، بلا تثبيت ولا رفع ولا نشر."},{question:"هل من الآمن لصق HTML من مصدر آخر؟",answer:"الإطار معزول: يشغّل السكربتات ليعمل سلوك المكوّن، ولا يستطيع الوصول إلى الصفحة أو تخزينها أو الكوكيز."},{question:"كيف أختبر المكوّن من اليمين إلى اليسار؟",answer:"بدّل زرّ الاتجاه. المبدّل يغيّر سمة dir في المستند نفسه، فترى سلوك الملف الحقيقي لا نتيجة مساعدة من الصفحة الأم."},{question:"هل أستطيع تحميل مكوّن من المكتبة؟",answer:"نعم، افتح الملعب مع معرّف القالب في رابط الصفحة فيصلك الملف محمّلاً جاهزاً للتعديل."}],related:[{to:"/ar/svg-toolkit",label:"أدوات SVG"},{to:"/ar/IconsGalary",label:"مكتبة الأيقونات"},{to:"/ar/tools",label:"كل أدوات المطوّرين"}]}};export{e as A,t as C,a as T};
